				$_SESSION['vat_type'] = $_POST['vat_type'];
				$_SESSION['vat_calc_type'] = $_POST['vat_calc_type'];
				$_SESSION['covid_perc'] = $_POST['covid_perc'];
				$_SESSION['nhil_perc'] = $_POST['nhil_perc'];
				$_SESSION['getfund_perc'] = $_POST['getfund_perc'];
				$_SESSION['vat_perc'] = $_POST['vat_perc'];
				$company_type_id = $_SESSION['company_type_id'];

				$sql = "SELECT * FROM `subscription_bill` WHERE `company_id` =? ORDER BY date_end DESC";
				$stmt = $con->prepare($sql); 
				$stmt->bind_param("i", $company_id);
				$stmt->execute();
				$stmt_result = $stmt->get_result();

				if($stmt_result->num_rows > 0)
				{
					$row_sub_bill = $stmt_result->fetch_assoc();
					/*$query_sub_bill = "SELECT * FROM `subscription_bill` WHERE `company_id`='$company_id'
					ORDER BY date_end DESC";
					$result_sub_bill = mysqli_query($con,$query_sub_bill);
					$row_sub_bill = mysqli_fetch_assoc($result_sub_bill);*/

					$date = date("Y-m-d");

					$date_grace = $row_sub_bill['date_grace'];
					$date_end = $row_sub_bill['date_end'];

					if($date_grace < $date)
					{
						$type = "Expired_Closed";
					}
					else if($date_grace >= $date)
					{
						if($date_end >= $date)
						{
							$_SESSION['company_id'] = $_POST['company_id'];
							$_SESSION['company_type_id'] = $_POST['company_type_id'];
							$_SESSION['company_sms'] = $_POST['company_sms'];
					
							$sql = "SELECT * FROM `branch` WHERE `company_id` =? ORDER BY branch_id ASC";
							$stmt = $con->prepare($sql); 
							$stmt->bind_param("i", $company_id);
							$stmt->execute();
							$stmt_result = $stmt->get_result();

							if($stmt_result->num_rows > 0)
							{
								$row = $stmt_result->fetch_assoc();
								/*$query = "SELECT * FROM branch WHERE company_id='".$_POST['company_id']."'
								ORDER BY branch_id ASC";
								$result = mysqli_query($con,$query);
								if(mysqli_num_rows($result) > 0)
								{
								$row = mysqli_fetch_assoc($result);*/
								$_SESSION['branch_id'] = $row['branch_id'];
								$_SESSION['warehouse_id'] = $row['warehouse_id'];
							};
							$type = "Open";
						}
						else
						{
							$_SESSION['company_id'] = $_POST['company_id'];
							$_SESSION['company_type_id'] = $_POST['company_type_id'];
							$_SESSION['company_sms'] = $_POST['company_sms'];
					
							$sql = "SELECT * FROM `branch` WHERE `company_id` =? ORDER BY branch_id ASC";
							$stmt = $con->prepare($sql); 
							$stmt->bind_param("i", $company_id);
							$stmt->execute();
							$stmt_result = $stmt->get_result();

							if($stmt_result->num_rows > 0)
							{
								$row = $stmt_result->fetch_assoc();
								/*$query = "SELECT * FROM branch WHERE company_id='".$_POST['company_id']."'
								ORDER BY branch_id ASC";
								$result = mysqli_query($con,$query);
								if(mysqli_num_rows($result) > 0)
								{
									$row = mysqli_fetch_assoc($result);*/
								$_SESSION['branch_id'] = $row['branch_id'];
								$_SESSION['warehouse_id'] = $row['warehouse_id'];
							};
							$type = "Expired_Grace";
						};
					};
				}
				else
				{
					$date_grace = '';
					$date_end = '';
					$type = '';
				};
		
				array_push($company_open_detail, 
					$date_grace,
					$date_end,
					$type,
					$company_type_id
				);
				echo json_encode($company_open_detail);
			}

