			function sms_edit()
			{
				global $con;
				$sms_id = $_POST['sms_id'];
				$query = "SELECT * FROM sms WHERE sms_id='$sms_id'";
				$result = mysqli_query($con,$query);
				$sms_detail = array();
				while($row = mysqli_fetch_assoc($result))
				{
					array_push($sms_detail, 
						$row['sms_id'],
						$row['date'],
						$row['qty_purchased'],
						$row['qty_sent'],
						$row['name'],
						$row['status']
					);
				}
					echo json_encode($sms_detail);
			}

			function sms_update()
			{
				global $con;
				$company_id = $_SESSION['company_id'];
				$sms_id = $_POST['sms_id'];
				$sms_date = $_POST['sms_date'];
				$sms_qty_purchased = $_POST['sms_qty_purchased'];
				$sms_qty_sent = $_POST['sms_qty_sent'];
				$sms_name = $_POST['sms_name'];
				$sms_status = $_POST['sms_status'];
				$user_id = $_SESSION['user_id'];
				$branch_id = $_SESSION['branch_id'];

				$query = "UPDATE `sms` SET `date`='$sms_date',`qty_purchased`='$sms_qty_purchased',
				`qty_sent`='$sms_qty_sent',`name`='$sms_name',
				`status`='$sms_status',`altered_by`='$user_id',`altered_datetime`=NOW() WHERE `sms_id`='$sms_id'";
				mysqli_query($con,$query);
			}

