			        if (isset($row_tb_3['tb_3_desc'])) {
			        	$tb_3_desc = $row_tb_3['tb_3_desc'];
			        }
			        else
			        {
			        	$tb_3_desc = 0;
			        }

			        $tb_4_id = $row['tb_4'];
