			function ledger_delete()
			{
				global $con;
				$status = '';
				$ledger_id = $_POST['ledger_id'];
				$query_trans = "SELECT * FROM transactions WHERE ledger_id = '$ledger_id' AND deleted=''";
				$query_run_trans = mysqli_query($con, $query_trans);
				if (mysqli_num_rows($query_run_trans) > 0)
				{
					$status = 'used';
				};
	
				if($status == '')
				{
					$query_delete = "DELETE FROM  ledgers WHERE ledger_id = '$ledger_id'";
					mysqli_query($con, $query_delete);

					$status = 'deleted';
				};
	
				echo $status;
			}

