			    $query = "UPDATE `stock_items` SET 
			    `stock_type`='$type', `stock_item`='$stock_item_name', `price_cash`='$price_cash', `unit_id`='$unit_of_measure',
				`manufacturer`='$manufacturer', `block_negative`='$block_neg', `block_expiry`='$expiry_date',
				`maintain_batch`='$batch', `days_to_promt`='$days_prompt', `eoq`='$eoq',`min_level`='$min_level', 
				`max_level`='$max_level', `re_order_level`='$re_order_level', `stock_item_type_id`='$stock_item_type_id', 
				`grams`='$grams', `price_per_gram`='$price_per_gram', `margin_site`='$margin_site', `margin_mtce`='$margin_mtce' 
				WHERE `stock_item_id`='$stock_item_id'";
			    $query_run = mysqli_query($con, $query);

			    if ($query_run)
			    {
			        $query_delete = "DELETE FROM `component_list` WHERE `stock_item_id`='$stock_item_id'";
					mysqli_query($con, $query_delete);

