								(`company_id`, `branch_id`, `stock_item_id`, `component_id`, `price_per_gram`, `grams`, `amount`, 
								`created_by`, `created_datetime`) VALUES 
								('$company_id','$branch_id','$stock_item_id','$component_id','$price','$gram','$amount',
								'$user_id',NOW())";
								mysqli_query($con, $query);
							};
						};
					};
			    };
