		    function stock_item_img_upload()
		    {
		    	global $con;
		    	if (isset($_POST['stock_item_img_save_btn']))
				{
		    		$stock_item_id = $_POST['stock_item_id_img'];
		    		$file = $_FILES['stock_item_img_file'];
		    		$fileName = $_FILES['stock_item_img_file']['name'];
		    		$fileType = $_FILES['stock_item_img_file']['type'];
		    		$fileError = $_FILES['stock_item_img_file']['error'];
		    		$fileSize = $_FILES['stock_item_img_file']['size'];
		    		$fileTmpName = $_FILES['stock_item_img_file']['tmp_name'];
		    		$company_id = $_SESSION['company_id'];
		    		$branch_id = $_SESSION['branch_id'];
		    		$user_id = $_SESSION['user_id'];

		    		$fileExt = explode('.', $fileName);
		    		$fileActualExt = strtolower(end($fileExt));

		    		$allowed = array('jpg', 'jpeg', 'png', 'pdf', 'jfif');

		    		if (in_array($fileActualExt, $allowed)) 
					{
		    			if ($fileError === 0) 
						{
		    				if ($fileSize < 1000000) 
							{
		    					$fileNameNew = $stock_item_id."_".uniqid('',true).".".$fileActualExt;
		    					$fileDestination = $_SERVER['DOCUMENT_ROOT'].'/img/patients/'.$fileNameNew;
		    					//$fileUrl = $_SERVER['DOCUMENT_ROOT'].'/img/patients/'.$fileNameNew;
		    					$fileUrl = '/img/patients/'.$fileNameNew;
								//!!! NEW LINE !!!
								$fileDestination = str_replace('\\','/',$fileDestination);
								$fileUrl = str_replace('\\','/',$fileUrl);

		    					move_uploaded_file($fileTmpName, $fileDestination);

		    					$query = "UPDATE `stock_items` SET `img`='$fileDestination', `img_url`='$fileUrl' 
								WHERE `stock_item_id`='$stock_item_id'";

			    				mysqli_query($con, $query);
		    					header("Location: /layout/items/stock_item_list.php?uploadsuccess");
		    				} 
							else 
							{
		    					echo "Your file is too big";
		    				};
		    				
		    			} 
						else 
						{
		    				echo "There was an error uploading your file";
		    			};
		    		}
		    		else
		    		{
		    			echo "You cannot upload files of this type";
		    		};
		    	};
		    }
			
		    function client_img_display_clear()
		    {
		    	global $con;
				$client_image = array();
				$client_img_id = $_POST['client_img_id'];
				$client_id = $_POST['client_id'];
				$query = "DELETE FROM `client_img` WHERE `client_img_id`='$client_img_id'";
				$query_run = mysqli_query($con, $query);

				$query = "SELECT * FROM `client_img` WHERE `client_id`='$client_id'";
				$query_run = mysqli_query($con, $query);
				while($row = mysqli_fetch_assoc($query_run))
				{
					$fileName = $row['img_url'];
					$fileExt = explode('.', $fileName);
					$fileActualExt = strtolower(end($fileExt));
					array_push($client_image, 
						$row['img_url'],
						$row['client_img_id'], 
						$row['client_id'], 
						$fileActualExt 
					);
				};
				
				echo json_encode($client_image);
		    }

			function delete_stock_item()
			{
				global $con;
				$status = '';
				$stock_item_id = $_POST['stock_item_id'];
				$query_purchases = "SELECT * FROM stock_purchase_items WHERE stock_item_id = '$stock_item_id'";
				   $query_run_purchases = mysqli_query($con, $query_purchases);
				if (mysqli_num_rows($query_run_purchases) > 0)
				{
					$status = 'used';
				};
				$query_sales = "SELECT * FROM stock_sales_items WHERE stock_item_id = '$stock_item_id'";
				   $query_run_sales = mysqli_query($con, $query_sales);
				if (mysqli_num_rows($query_run_sales) > 0)
				{
					$status = 'used';
				};
				$query_transfer = "SELECT * FROM stock_transfer_items WHERE stock_item_id = '$stock_item_id'";
				   $query_run_transfer = mysqli_query($con, $query_transfer);
				if (mysqli_num_rows($query_run_transfer) > 0)
				{
					$status = 'used';
				};
				$query_adjustment = "SELECT * FROM stock_adjustment_items WHERE stock_item_id = '$stock_item_id'";
				   $query_run_adjustment = mysqli_query($con, $query_adjustment);
				if (mysqli_num_rows($query_run_adjustment) > 0)
				{
					$status = 'used';
				};
				$query_requisition = "SELECT * FROM stock_requisition_items WHERE stock_item_id = '$stock_item_id'";
				   $query_run_requisition = mysqli_query($con, $query_requisition);
				if (mysqli_num_rows($query_run_requisition) > 0)
				{
					$status = 'used';
				};
	
				if($status == '')
				{
					$query_delete = "DELETE FROM  stock_items WHERE stock_item_id = '$stock_item_id'";
					mysqli_query($con, $query_delete);

					$query_delete = "DELETE FROM  component_list WHERE stock_item_id = '$stock_item_id'";
					mysqli_query($con, $query_delete);

					$status = 'deleted';
				};
	
				echo $status;
			}
			
			function stock_item_auto_price_update()
			{
				global $con;
				$counter = 0;
				$type = $_POST['type'];
				$category = $_POST['category'];
				$component_id = $_POST['component_id'];
				$amount = $_POST['amount'];
				$company_id = $_SESSION['company_id'];
				$new_price = 0;
				$stock_item_id = 0;
				$old_price = 0;
				$grams = 0;
				$price_per_gram = 0;
				if(!empty($category) && ($component_id == 0 || $component_id == ''))
				{
					if($category == 'ALL' || $category == 'all')
					{
						$query = "SELECT * FROM stock_items WHERE company_id = '$company_id'";
					}
					else
					{
						$query = "SELECT * FROM stock_items WHERE company_id = '$company_id' AND 
						stock_type LIKE '%".$category."%'";
					};

					$query_run = mysqli_query($con, $query);
					if (mysqli_num_rows($query_run) > 0)
					{
						while($row = mysqli_fetch_assoc($query_run))
						{
							$stock_item_id = $row['stock_item_id'];
							$grams = $row['grams'];
							$old_price_per_gram = $row['price_per_gram'];
							$old_price = $row['price_cash'];

							if($type == 'Increase_By_Percentage')
							{
								$new_price_per_gram = $old_price_per_gram + ($old_price_per_gram * $amount);
								$selling_price = $grams * $new_price_per_gram;
							};

							if($type == 'Increase_By_Amount')
							{
								$new_price_per_gram = $old_price_per_gram + $amount;
								$selling_price = $grams * $new_price_per_gram;
							};

							if($type == 'Decrease_By_Percentage')
							{
								$new_price_per_gram = $old_price_per_gram - ($old_price_per_gram * $amount);
								$selling_price = $grams * $new_price_per_gram;
							};

							if($type == 'Decrease_By_Amount')
							{
								$new_price_per_gram = $old_price_per_gram - $amount;
								$selling_price = $grams * $new_price_per_gram;
							};
							
							$query_update = "UPDATE stock_items SET price_cash = '$selling_price',  price_per_gram = '$new_price_per_gram'
							WHERE stock_item_id = '$stock_item_id'";
							mysqli_query($con, $query_update);
							$counter = $counter + 1;
						};
					};
				}
				else if($component_id > 0 && empty($category))
				{
					$new_price_per_gram = 0;
					$query = "SELECT * FROM component WHERE component_id = '$component_id'";
					$query_run = mysqli_query($con, $query);
					if (mysqli_num_rows($query_run) > 0)
					{
						while($row = mysqli_fetch_assoc($query_run))
						{
							$old_price_per_gram = $row['price_per_gram'];
							
							if($type == 'Increase_By_Percentage')
							{
								$new_price_per_gram = $old_price_per_gram + ($old_price_per_gram * $amount);
							};

							if($type == 'Increase_By_Amount')
							{
								$new_price_per_gram = $old_price_per_gram + $amount;
							};

							if($type == 'Decrease_By_Percentage')
							{
								$new_price_per_gram = $old_price_per_gram - ($old_price_per_gram * $amount);
							};

							if($type == 'Decrease_By_Amount')
							{
								$new_price_per_gram = $old_price_per_gram - $amount;
							};
							
							$query_update = "UPDATE component SET  price_per_gram = '$new_price_per_gram'
							WHERE component_id = '$component_id'";
							mysqli_query($con, $query_update);

							
							$query_comlist = "SELECT * FROM component_list WHERE component_id = '$component_id'";
							$query_run_comlist = mysqli_query($con, $query_comlist);
							if (mysqli_num_rows($query_run_comlist) > 0)
							{
								while($row_comlist = mysqli_fetch_assoc($query_run_comlist))
								{
									$component_list_id = $row_comlist['component_list_id'];
									$grams = $row_comlist['grams'];
									$new_amount = $grams * $new_price_per_gram;

									$query_update = "UPDATE component_list SET  price_per_gram = '$new_price_per_gram',
									amount = '$new_amount' WHERE component_list_id = '$component_list_id'";
									mysqli_query($con, $query_update);
								};
							};
						};
					};
					
					$query_stock_item = "SELECT * FROM stock_items WHERE company_id = '$company_id'";
					$query_run_stock_item = mysqli_query($con, $query_stock_item);
					if (mysqli_num_rows($query_run_stock_item) > 0)
					{
						while($row_stock_item = mysqli_fetch_assoc($query_run_stock_item))
						{
							$stock_item_grams = $row_stock_item['grams'];
							$stock_item_id = $row_stock_item['stock_item_id'];
						
							$query_stock_item_cl = "SELECT * FROM component_list WHERE stock_item_id = '$stock_item_id'
							AND component_id = '$component_id'";
							$query_run_stock_item_cl = mysqli_query($con, $query_stock_item_cl);
							if (mysqli_num_rows($query_run_stock_item_cl) > 0)
							{
								$query_sicl = "SELECT SUM(price_per_gram) AS price_per_gram FROM component_list 
								WHERE stock_item_id = '$stock_item_id'";
								$query_run_sicl = mysqli_query($con, $query_sicl);
								if (mysqli_num_rows($query_run_sicl) > 0)
								{
									$row_sicl = mysqli_fetch_assoc($query_run_sicl);
									$price_per_gram = $row_sicl['price_per_gram'];
									$new_price = $stock_item_grams * $price_per_gram;

									$query_update = "UPDATE stock_items SET  price_per_gram = '$price_per_gram',
									price_cash = '$new_price' WHERE stock_item_id = '$stock_item_id'";
									mysqli_query($con, $query_update);
								};
								
								$counter = $counter + 1;
							};
						};
					};
				};

				echo $counter;
			}

