				global $con;
				$refrigerator_id = $_POST['refrigerator_id'];
				$refrigerator_name = $_POST['refrigerator_name'];
				$refrigerator_price = $_POST['refrigerator_price'];
				$company_id = $_SESSION['company_id'];
				$branch_id = $_SESSION['branch_id'];
				$user_id = $_SESSION['user_id'];

				if($company_id > 0)
				{
					$query_last_sno = "SELECT `sno` FROM `refrigerator` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
					$result_last_sno = mysqli_query($con,$query_last_sno);
					$row_last_sno = mysqli_fetch_assoc($result_last_sno);
					$last_sno = $row_last_sno['sno'];
					$next_sno = $last_sno + 1;

					$query = "INSERT INTO `refrigerator`(`sno`,`branch_id`,`refrigerator`,`price`,`company_id`,
					`created_by`,`created_datetime`) VALUES ('$next_sno','$branch_id','$refrigerator_name',
					'$refrigerator_price','$company_id','$user_id',NOW())";
					$query_run = mysqli_query($con, $query);
					if ($query_run) 
					{
