			function current_date()
			{
				date_default_timezone_set('Africa/Accra');
				$date = date('m/d/Y h:i:s a', time());
				echo $date;
			}

			function age($dob)
			{
				$dateOfBirth = $dob;
				$today = date("Y-m-d");
				$diff = date_diff(date_create($dateOfBirth), date_create($today));
				echo $diff->format('%y');
			}
			
			function nexusora($voucher, $ledger, $date, $amount, $narration, $reference, $voucher_id, $debit_ledger, $credit_ledger, $branch_id, $company_id)
			{
				global $con;
				//DEBIT
					$query_ledger = "SELECT ledger_desc, tb_4 FROM ledgers WHERE `ledger_id`='$debit_ledger' LIMIT 1";
					$result_ledger = mysqli_query($con,$query_ledger);
					if(!empty($result_ledger) && mysqli_num_rows($result_ledger) > 0)
					{
						$row_ledger = mysqli_fetch_assoc($result_ledger);
						$dr_ledger_desc = $row_ledger['ledger_desc'];
						$dr_tb_4 = $row_ledger['tb_4'];
					}
					else
					{
						$dr_ledger_desc = "Not Specified";
						$dr_tb_4 = 0;
					};
				//CREDIT
					$query_ledger = "SELECT ledger_desc, tb_4 FROM ledgers WHERE `ledger_id`='$credit_ledger' LIMIT 1";
					$result_ledger = mysqli_query($con,$query_ledger);
					if(!empty($result_ledger) && mysqli_num_rows($result_ledger) > 0)
					{
						$row_ledger = mysqli_fetch_assoc($result_ledger);
						$cr_ledger_desc = $row_ledger['ledger_desc'];
						$cr_tb_4 = $row_ledger['tb_4'];
					}
					else
					{
						$cr_ledger_desc = "Not Specified";
						$cr_tb_4 = 0;
					};


				// 1. Define the API endpoint and your authentication token
					$url = 'https://kgr.nexusorabooks.com/external/v1/vouchers/mapped';
					$apiToken = 'nbk_live_7908e4054bc4b5749832e74ba7dca80bb7dcabcda4573a0efbed982496a28a16'; // Replace with your actual NexusOra API key

				// 2. Prepare the payload data as a native PHP array
					/*$data = [
						"source" => "kgr_php_gold",
						"record" => [
							"txn_type"    => $voucher,
							"txn_date"    => $date,
							"value"       => $amount,
							"memo"        => $narration,
							"voucher_ref" => $reference,
							"row_id"      => $voucher_id,
							"party"       => $dr_ledger_desc,
							"dr_acct"     => $debit_ledger,
							"cr_acct"     => $credit_ledger,
							"branch"     => $branch_id
						]
					];*/

					// row_id must be globally unique across voucher types, because Books
					// dedups on externalId. purchase_id, receipt_id, payment_id, etc. are
					// separate sequences, so a plain numeric row_id collides across types
					// (purchase #5 vs receipt #5) and the later one is rejected as a
					// duplicate (HTTP 409). Namespacing by type prevents that.
					$unique_row_id = $voucher . '-' . $voucher_id;

					$data = [
						"source"=>"kgr_php_gold", 
						"record"=> 
						[
							"row_id"=> $unique_row_id,
							"company_id"=>$company_id, 
							"type"=> $voucher,
							"date"=> $date, 
							"amount"=> $amount,
							"dr_ledger_id"=> $debit_ledger,
							"dr_group"=>$dr_tb_4, 
							"dr_desc"=>$dr_ledger_desc,
							"cr_ledger_id"=> $credit_ledger, 
							"cr_group"=>$cr_tb_4, 
							"cr_desc"=>$cr_ledger_desc,
							"branch"=> $branch_id
						]
					];


				// 3. Convert the array to a JSON string
					$payload = json_encode($data);

				// 4. Initialize and configure the cURL session
					$ch = curl_init($url);

					curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
					curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "POST");
					curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
					// Timeouts so a slow or unreachable Books API can never hang the save.
					curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 5);
					curl_setopt($ch, CURLOPT_TIMEOUT, 10);

				// Set the necessary HTTP headers for JSON and Authorization
					curl_setopt($ch, CURLOPT_HTTPHEADER, [
						'Content-Type: application/json',
						'Authorization: Bearer ' . $apiToken,
						'Content-Length: ' . strlen($payload)
					]);

				// 5. Execute the request and handle the response
					$response = curl_exec($ch);
					$httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

					// Never echo here: this runs inside the voucher-save AJAX handlers, so
					// any echo corrupts the JSON the browser parses. Log instead so failures
					// are visible and debuggable.
					$log_line = date("Y-m-d H:i:s") . " | " . $voucher . " | row_id=" . $unique_row_id . " | ";
					if (curl_errno($ch)) {
						$log_line .= "cURL ERROR: " . curl_error($ch);
					} else {
						$log_line .= "HTTP " . $httpCode . " | " . $response;
					}
					error_log($log_line . PHP_EOL, 3, $_SERVER["DOCUMENT_ROOT"] . "/includes/nexusora_integration.log");

				// 6. Close the session
					curl_close($ch);

			}
