			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$company_id = $_SESSION['company_id'];

			if($company_id > 0)
			{
				$query_last_sno = "SELECT `sno` FROM `admission` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
				$result_last_sno = mysqli_query($con,$query_last_sno);
				$row_last_sno = mysqli_fetch_assoc($result_last_sno);
				$last_sno = $row_last_sno['sno'];
				$next_sno = $last_sno + 1;

				$query = "INSERT INTO `admission`(
				`company_id`,`branch_id`, `sno`, `deceased`,`refrigerator_id`, `cubicle_id`, `tag_id`, 
				`date_admitted`, `date_discharged`, `sex`, `age`, `cause_of_death`, `death_certificate`, `place_of_death`, 
				`pathologist`, `relative`, `relative_phone_no`, `relative_address`, `attendant`, `created_by`, 
				`created_datetime`,`amount_stock`,`amount_service`,`amount_total`) VALUES (
				'$company_id','$branch_id','$next_sno','$deseased','$refrigerator_id','$cubicle_id','$tag','$admission_date',
				'$discharge_date','$gender','$age','$cause_of_death','$certificate','$place_of_death','$pathologist','$relative',
				'$relative_phone','$relative_address','$attendant','$user_id',NOW(),'$total_stock_amount','$total_service_amount','$total_amount')";
				$query_run = mysqli_query($con, $query);
				if ($query_run) 
				{
					//POST TRANSACTION
						$query = "SELECT * FROM admission WHERE `company_id`='$company_id' ORDER BY admission_id DESC";
						$result = mysqli_query($con,$query);
						$row = mysqli_fetch_assoc($result);
						$admission_id = $row['admission_id'];
						$_SESSION['admission_id'] = $row['admission_id'];

					//STOCK LIST
						$number_stk = count($_POST["admission_stock_item_id"]);  
						if($number_stk > 0)  
						{  
							for($i=0; $i<$number_stk; $i++)  
							{  
								if(trim($_POST["admission_stock_item_id"][$i]) != '' && trim($_POST["admission_stock_item_id"][$i]) > 0)
								{  
									$item_id = $_POST['admission_stock_item_id'][$i];
									$warehouse_id = $_POST['admission_warehouse_id'][$i];
									$qty = $_POST['admission_stock_qty'][$i];
									$price = $_POST['admission_stock_price'][$i];
									$amount = $_POST['admission_stock_amount'][$i];

									$query_stock_item = "SELECT * from stock_items where stock_item_id='$item_id'";
									$result_stock_item = mysqli_query($con,$query_stock_item);
									if(!empty($result_stock_item) && mysqli_num_rows($result_stock_item) > 0)
									{
										$row_stock_item = mysqli_fetch_assoc($result_stock_item);
