		function update_admission()
		{
			global $con;
			$userdetail = $_SESSION['full_name'].':-'.time();
			$admission_id = $_POST['admission_id'];
			$_SESSION['admission_id'] = $_POST['admission_id'];
			$deseased = $_POST['admission_deseased'];
			$age = $_POST['admission_age'];
			$gender = $_POST['admission_gender'];
			$tag = $_POST['admission_tag'];
			$refrigerator_id = $_POST['admission_refrigerator_initial'];
			$cubicle_id = $_POST['admission_refrigerator_cubible_initial'];
			$admission_date = $_POST['admission_date'];
			$discharge_date = $_POST['discharge_date'];
			$cause_of_death = $_POST['admission_cause_of_death'];
			$place_of_death = $_POST['admission_place_of_death'];
			$certificate = $_POST['admission_certificate'];
			$pathologist = $_POST['admission_pathologist'];
			$relative = $_POST['admission_relative'];
			$relative_phone = $_POST['admission_relative_phone'];
			$relative_address = $_POST['admission_relative_address'];
			$attendant = $_POST['admission_attendant'];
			$total_stock_amount = $_POST['admission_total_stock_amount'];
			$total_service_amount = $_POST['admission_total_service_amount'];
			$total_amount = $_POST['admission_total_amount'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$company_id = $_SESSION['company_id'];

			if($company_id > 0)
			{
				$query = "UPDATE `admission` SET
				`deceased`='$deseased',`refrigerator_id`='$refrigerator_id', `cubicle_id`='$cubicle_id', 
				`tag_id`='$tag', `date_admitted`='$admission_date', `date_discharged`='$discharge_date', 
				`sex`='$gender', `age`='$age', `cause_of_death`='$cause_of_death', `death_certificate`='$certificate', 
				`place_of_death`='$place_of_death', `pathologist`='$pathologist', `relative`='$relative', 
				`relative_phone_no`='$relative_phone', `relative_address`='$relative_address', 
				`attendant`='$attendant', `altered_by`='$user_id', `altered_datetime`=NOW(),
				`amount_stock`='$total_stock_amount',`amount_service`='$total_service_amount',
				`amount_total`='$total_amount' WHERE `admission_id`='$admission_id'";
				$query_run = mysqli_query($con, $query);
				if ($query_run) 
				{
					//POST TRANSACTION
					if(isset($admission_id) && $admission_id > 0)
					{
						$query_del = "DELETE FROM admission_stock WHERE `admission_id`='$admission_id'";
						mysqli_query($con,$query_del);
						$query_del = "DELETE FROM admission_service WHERE `admission_id`='$admission_id'";
						mysqli_query($con,$query_del);
						$query_del = "DELETE FROM refrigerator_list WHERE `admission_id`='$admission_id'";
						mysqli_query($con,$query_del);
						$query_del = "DELETE FROM transactions WHERE `admission_id`='$admission_id'";
						mysqli_query($con,$query_del);
						
						//STOCK LIST
							$number_stk = count($_POST["admission_stock_item_id"]);  
							if($number_stk > 0)  
							{  
								for($i=0; $i<$number_stk; $i++)  
								{  
									if(trim($_POST["admission_stock_item_id"][$i]) != '' && trim($_POST["admission_stock_item_id"][$i]) > 0)
									{  
										$item_id = $_POST['admission_stock_item_id'][$i];
										$warehouse_id = $_POST['admission_warehouse_id'][$i];
										$qty = $_POST['admission_stock_qty'][$i];
										$price = $_POST['admission_stock_price'][$i];
										$amount = $_POST['admission_stock_amount'][$i];

										$query_stock_item = "SELECT * from stock_items where stock_item_id='$item_id'";
										$result_stock_item = mysqli_query($con,$query_stock_item);
										if(!empty($result_stock_item) && mysqli_num_rows($result_stock_item) > 0)
										{
											$row_stock_item = mysqli_fetch_assoc($result_stock_item);
											if(isset($row_stock_item['sales_ledger_id']) && $row_stock_item['sales_ledger_id'] > 0)
											{
												$sales_ledger_id = $row_stock_item['sales_ledger_id'];
											}
											else
											{
												$sales_ledger_id = 35;
											};
											$stock_item = $row_stock_item['stock_item'];
										}
										else
										{
											$sales_ledger_id = 35;
											$stock_item = 'N/A';
										};
										$stock_narration = ' sale of '.$qty.' '.$stock_item.' @ '.$price;

										$query_as = "INSERT INTO `admission_stock`
										(`company_id`, `branch_id`, `admission_id`, `warehouse_id`, `date`, `qty`, `price`, `amount`, `stock_item_id`,
										`created_by`, `created_datetime`) VALUES ('$company_id','$branch_id','$admission_id','$warehouse_id',
										'$admission_date','$qty','$price','$amount','$item_id','$user_id',NOW())";
										mysqli_query($con, $query_as);

										$query_dr = "INSERT INTO `transactions`(
										`company_id`,`admission_id`,`ledger_id`,  `ledger_id_contra`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`) VALUES (
										'$company_id','$admission_id',40,'$sales_ledger_id','$admission_date',
										'$amount','$amount',0,'$stock_narration','$user_id',NOW())";
										mysqli_query($con, $query_dr);

										$query_cr = "INSERT INTO `transactions`(
										`company_id`,`admission_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`) VALUES (
										'$company_id','$admission_id','$sales_ledger_id',40,'$admission_date',
										'$amount',0,'$amount','$stock_narration','$user_id',NOW())";
										mysqli_query($con, $query_cr);
									};
								};
							};

						//SERVICES LIST
							$number_srv = count($_POST["admission_ledger_id"]);  
							if($number_srv > 0)  
							{  
								for($i=0; $i < $number_srv; $i++)
								{  
									if(trim($_POST["admission_ledger_id"][$i]) != '' && trim($_POST["admission_ledger_id"][$i]) > 0)
									{  
										$ledger_id = $_POST['admission_ledger_id'][$i];
										$qty = $_POST['admission_service_qty'][$i];
										$price = $_POST['admission_service_price'][$i];
										$amount = $_POST['admission_service_amount'][$i];

										$query_ledger = "SELECT * from ledgers where ledger_id='$ledger_id'";
										$result_ledger = mysqli_query($con,$query_ledger);
										if(!empty($result_ledger) && mysqli_num_rows($result_ledger) > 0)
										{
											$row_ledger = mysqli_fetch_assoc($result_ledger);
											if(isset($row_ledger['sales_ledger_id']) && $row_ledger['sales_ledger_id'] > 0)
											{
												$ledger_desc = $row_ledger['ledger_desc'];
											}
											else
											{
												$ledger_desc = 'N/A';
											};
										}
										else
										{
											$ledger_desc = 'N/A';
										};
										$service_narration = $ledger_desc.' @ '.$price;

										$query_asv = "INSERT INTO `admission_service`
										(`company_id`, `branch_id`, `admission_id`, `date`, `qty`, `price`, `amount`, `ledger_id`,
										`created_by`, `created_datetime`) VALUES ('$company_id','$branch_id','$admission_id',
										'$admission_date','$qty','$price','$amount','$ledger_id','$user_id',NOW())";
										mysqli_query($con, $query_asv);

										$query_dr = "INSERT INTO `transactions`(
										`admission_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `branch_id`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`) VALUES (
										'$admission_id',40,'$ledger_id','$company_id','$branch_id','$admission_date',
										'$amount','$amount',0,'$service_narration','$user_id',NOW())";
										mysqli_query($con, $query_dr);

										$query_cr = "INSERT INTO `transactions`(
										`admission_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `branch_id`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`) VALUES (
										'$admission_id','$ledger_id',40,'$company_id','$branch_id','$admission_date',
										'$amount',0,'$amount','$service_narration','$user_id',NOW())";
										mysqli_query($con, $query_cr);
									};
								};
							};

						//REFRIGERATOR
							$number_ref = count($_POST["admission_refrigerator_id"]);  
							$fridge_count = 0; 
							if($number_ref > 0)  
							{  
								for($i=0; $i < $number_ref; $i++)
								{  
									if(trim($_POST["admission_refrigerator_id"][$i]) != '' && trim($_POST["admission_refrigerator_id"][$i]) > 0)
									{  
										if(trim($_POST["admission_refrigerator_id"][$i]) > 0){$fridge_count++;};
										$refrigerator_id = $_POST['admission_refrigerator_id'][$i];
										$date_admitted = $_POST['admission_refrigerator_date_admitted'][$i];
										$date_discharge = $_POST['admission_refrigerator_date_discharge'][$i];
										$cubicle_id = $_POST['admission_refrigerator_cubible'][$i];

										$query_asv = "INSERT INTO `refrigerator_list`(`company_id`, `branch_id`, `refrigerator_id`, 
										`cubicle_id`,`admission_id`, `date_admitted`, `date_discharged`,`created_by`, `created_datetime`) 
										VALUES ('$company_id','$branch_id','$refrigerator_id','$cubicle_id','$admission_id',
										'$date_admitted','$date_discharge','$user_id',NOW())";
										mysqli_query($con, $query_asv);
									};
								};
							}
							else
							{
								$query_asv = "INSERT INTO `refrigerator_list`
								(`company_id`, `branch_id`, `refrigerator_id`, `cubicle_id`,`admission_id`, `date_admitted`, `date_discharged`,
								`created_by`, `created_datetime`) VALUES ('$company_id','$branch_id','$refrigerator_id',
								'$cubicle_id','$admission_id','$admission_date','$discharge_date','$user_id',NOW())";
								mysqli_query($con, $query_asv);
								$fridge_count++;
							};
							if($fridge_count < 1)
							{
								$query_asv = "INSERT INTO `refrigerator_list`
								(`company_id`, `branch_id`, `refrigerator_id`, `cubicle_id`,`admission_id`, `date_admitted`, `date_discharged`,
								`created_by`, `created_datetime`) VALUES ('$company_id','$branch_id','$refrigerator_id',
								'$cubicle_id','$admission_id','$admission_date','$discharge_date','$user_id',NOW())";
								mysqli_query($con, $query_asv);
							};
					};
				};
			};
		}
		
		function admission_refrigerator_transfer()
		{
			global $con;
			$admission_id = $_POST['admission_id'];
			$details = array();
			$query_ref = "SELECT * FROM refrigerator_list WHERE admission_id='$admission_id' ORDER BY refrigerator_list_id DESC";
			$result_ref = mysqli_query($con,$query_ref);
			$row_ref = mysqli_fetch_assoc($result_ref);

			array_push($details, 
				$row_ref['refrigerator_list_id'],$row_ref['refrigerator_id'],$row_ref['cubicle_id'],$row_ref['date_admitted'],
				$row_ref['admission_id']
			);
			echo json_encode($details);
		}
		
