		function edit_receipt()
		{
			global $con;
			$receipt_id = $_POST['receipt_id'];
			$receipt_details=array();
			$query = "SELECT * FROM receipt WHERE receipt_id='$receipt_id'";
			$result = mysqli_query($con,$query);
			while($row = mysqli_fetch_assoc($result))
			{
				array_push($receipt_details, 
					$row['user_super_id'],$row['receipt_id'],$row['company_id'],$row['user_id'],$row['ledger_credit'],
					$row['ledger_debit'],$row['received_from'],$row['date'],$row['amount'],$row['narration'],$row['reference_no'],
					$row['mode'],$row['bank'],$row['branch'],$row['inst_no'],$row['branch_id'],$row['job_card_id'],$row['admission_id']
				);
			}
			 echo json_encode($receipt_details);
		}

