		function delete_receipt()
		{
			global $con;
			$userdetail = $_SESSION['full_name'].':-'.time();
			$receipt_id = trim($_POST['receipt_id']);
			if(isset($receipt_id) && $receipt_id > 0)
			{
				//$receipt_id = $_POST['receipt_id'];
				$query = "UPDATE `receipt` SET deleted='$userdetail' WHERE `receipt_id`='$receipt_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					$query_trans_del = "DELETE FROM `transactions` WHERE `receipt_id`='$receipt_id'";
					mysqli_query($con, $query_trans_del);
					
					echo "Receipt DELETED Successfully";  
				}  
				else  
				{  
					echo "Receipt NOT DELETED";  
				};
			};
		}


