		function save_payment()
		{
			global $con;
			$payment_id = $_POST['payment_id'];
			if(isset($_POST['payment_branch_id']) && $_POST['payment_branch_id'] > 0)
			{
				$branch_id = $_POST['payment_branch_id'];
			}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			$user_super_id = $_POST['user_super_id'];
			$payment_credit_ledger = $_POST['payment_credit_ledger'];
			$payment_ref = $_POST['payment_ref'];
			$payment_date = $_POST['payment_date'];
			$payment_amount = $_POST['payment_amount'];
			$payment_mode = $_POST['payment_mode'];
			$payment_inst_no = $_POST['payment_inst_no'];
			$payment_bank = $_POST['payment_bank'];
			$payment_branch = $_POST['payment_branch'];
			$payment_payee = $_POST['payment_payee'];
			$payment_narration = addslashes($_POST['payment_narration']);

			if($company_id > 0)
			{
				$query_last_sno = "SELECT `sno` FROM `payment` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
				$result_last_sno = mysqli_query($con,$query_last_sno);
						
				if (!empty($result_last_sno) && mysqli_num_rows($result_last_sno) > 0)
				{
					$row_last_sno = mysqli_fetch_assoc($result_last_sno);
					$last_sno = $row_last_sno['sno'];
					$next_sno = $last_sno + 1;
				}
				else
				{
					$next_sno = 1;
				};

				$query = "INSERT INTO `payment`(
				`sno`,`company_id`, `user_id`, `user_super_id`, `ledger_credit`, `date`, `amount`, `narration`, `reference_no`, `mode`, `bank`, `branch`, `inst_no`, 
				`payee`,`branch_id`, `created_by`, `created_datetime`) VALUES ('$next_sno','$company_id','$user_id','$user_super_id','$payment_credit_ledger','$payment_date','$payment_amount','$payment_narration',
				'$payment_ref','$payment_mode','$payment_bank','$payment_branch','$payment_inst_no','$payment_payee','$branch_id','$user_id',NOW())";
				$query_run = mysqli_query($con, $query);
				if ($query_run) 
				{
					//POST TRANSACTION
						$query_select = "SELECT * FROM payment WHERE `company_id`='$company_id' ORDER BY payment_id DESC";
						$result_select = mysqli_query($con,$query_select);
						
						if (!empty($result_select) && mysqli_num_rows($result_select) > 0)
						{
							$row_select = mysqli_fetch_assoc($result_select);
							$payment_id = $row_select['payment_id'];
						}
						else
						{
							$payment_id = 0;
						};
						$_SESSION['payment_id'] = $payment_id;

						//PAYMENT_ITEMS
							$number_as = count($_POST["payment_led_dr"]);  
							if($number_as > 0)  
							{  
								for($i=0; $i<$number_as; $i++)  
								{  
									if(trim($_POST["payment_led_dr"][$i] != ''))
									{  
										$payment_led_dr = $_POST['payment_led_dr'][$i];
										$payment_site_dr = $_POST['payment_site_dr'][$i];
										$payment_asset_dr = $_POST['payment_asset_dr'][$i];
										$payment_dr_amt = $_POST['payment_dr_amt'][$i];
										$payment_dr_narration = addslashes($_POST['payment_dr_narration'][$i]);

										$query_dr = "INSERT INTO `transactions`(
										`payment_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `site_id`, `asset_id`) VALUES (
										'$payment_id','$payment_led_dr','$payment_credit_ledger','$company_id','$user_id','$user_super_id','$payment_date',
										'$payment_dr_amt','$payment_dr_amt',0,'$payment_dr_narration','$payment_site_dr','$payment_asset_dr')";
										mysqli_query($con, $query_dr);

										$query_cr = "INSERT INTO `transactions`(
										`payment_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `site_id`, `asset_id`) VALUES (
										'$payment_id','$payment_credit_ledger','$payment_led_dr','$company_id','$user_id','$user_super_id','$payment_date',
										'$payment_dr_amt',0,'$payment_dr_amt','$payment_dr_narration','$payment_site_dr','$payment_asset_dr')";
										mysqli_query($con, $query_cr);

										
										if($company_id == 328 || $company_id == 329)
										{
											nexusora('payment', $payment_led_dr, $payment_date, $payment_dr_amt, $payment_dr_narration, $payment_ref, $payment_id, $payment_led_dr, $payment_credit_ledger, $branch_id, $company_id);
										};
									};
								}; 
							};
				};
			};
		}

		function edit_payment()
		{
			global $con;
			$payment_id = $_POST['payment_id'];
			$payment_details=array();
			$query = "SELECT * FROM payment WHERE payment_id='$payment_id'";
			$result = mysqli_query($con,$query);
			while($row = mysqli_fetch_assoc($result))
			{
				array_push($payment_details, 
					$row['user_super_id'],$row['payment_id'],$row['company_id'],$row['user_id'],$row['ledger_credit'],
					$row['ledger_debit'],$row['payee'],$row['date'],$row['amount'],$row['narration'],$row['reference_no'],
					$row['mode'],$row['bank'],$row['branch'],$row['inst_no'],$row['branch_id']
				);
			}
			 echo json_encode($payment_details);
		}

