		function update_payment()
		{
			global $con;
			$userdetail = $_SESSION['full_name'].':-'.time();
			$payment_id = $_POST['payment_id'];
			$_SESSION['payment_id'] = $_POST['payment_id'];
			$company_id = $_SESSION['company_id'];
			if(isset($_POST['payment_branch_id']) && $_POST['payment_branch_id'] > 0)
			{
				$branch_id = $_POST['payment_branch_id'];
			}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};
			$user_id = $_SESSION['user_id'];
			$user_super_id = $_POST['user_super_id'];
			$payment_credit_ledger = $_POST['payment_credit_ledger'];
			$payment_ref = $_POST['payment_ref'];
			$payment_date = $_POST['payment_date'];
			$payment_amount = $_POST['payment_amount'];
			$payment_mode = $_POST['payment_mode'];
			$payment_inst_no = $_POST['payment_inst_no'];
			$payment_bank = $_POST['payment_bank'];
			$payment_branch = $_POST['payment_branch'];
			$payment_payee = $_POST['payment_payee'];
			$payment_narration = addslashes($_POST['payment_narration']);
			
			if($company_id > 0)
			{
				$query = "UPDATE `payment` SET
				`company_id`='$company_id', `user_id`='$user_id', `user_super_id`='$user_super_id', `ledger_credit`='$payment_credit_ledger', `date`='$payment_date', 
				`amount`='$payment_amount', `narration`='$payment_narration', `reference_no`='$payment_ref', `mode`='$payment_mode', `bank`='$payment_bank', 
				`branch`='$payment_branch', `inst_no`='$payment_inst_no', `branch_id`='$branch_id', `payee`='$payment_payee', `altered_by`='$user_id', `altered_datetime`=NOW() 
				WHERE `payment_id`='$payment_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					if(isset($payment_id) && $payment_id > 0)
					{
					//POST TRANSACTION
						$query = "DELETE FROM `transactions` WHERE `payment_id`='$payment_id'";
						mysqli_query($con,$query);

						//PAYMENT_ITEMS
						$number_as = count($_POST["payment_led_dr"]);  
						if($number_as > 0)  
						{  
							for($i=0; $i<$number_as; $i++)  
							{  
								if(trim($_POST["payment_led_dr"][$i] != ''))
								{  
									$payment_led_dr = $_POST['payment_led_dr'][$i];
									$payment_site_dr = $_POST['payment_site_dr'][$i];
									$payment_asset_dr = $_POST['payment_asset_dr'][$i];
									$payment_dr_amt = $_POST['payment_dr_amt'][$i];
									$payment_dr_narration = addslashes($_POST['payment_dr_narration'][$i]);

									$query_dr = "INSERT INTO `transactions`(
									`payment_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`, `site_id`, `asset_id`) VALUES (
									'$payment_id','$payment_led_dr','$payment_credit_ledger','$company_id','$user_id','$user_super_id','$payment_date',
									'$payment_dr_amt','$payment_dr_amt',0,'$payment_dr_narration','$payment_site_dr','$payment_asset_dr')";
									mysqli_query($con, $query_dr);

									$query_cr = "INSERT INTO `transactions`(
									`payment_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`, `site_id`, `asset_id`) VALUES (
									'$payment_id','$payment_credit_ledger','$payment_led_dr','$company_id','$user_id','$user_super_id','$payment_date',
									'$payment_dr_amt',0,'$payment_dr_amt','$payment_dr_narration','$payment_site_dr','$payment_asset_dr')";
									mysqli_query($con, $query_cr);
								};
							}; 
						};
					};
				};
			};
		}

