	    function update_purchase_invoice()
		{
			global $con;
			$userdetail = $_SESSION['full_name'].':-'.time();
			$purchase_id = $_POST['purchase_id'];
			$company_id = $_POST['purch_company_id'];
			$branch_id = $_POST['purch_branch_id'];
			$site_id = $_POST['purch_site'];
			$site_id = $_POST['purch_site'];
			$user_super_id = $_POST['purch_user_super_id'];
			$user_id = $_POST['purch_user_id'];
			$purch_debit = $_POST['purch_debit'];
			$purch_credit = $_POST['purch_credit'];
			$purch_date = $_POST['purch_date'];
			$purch_supplied_by = $_POST['purch_supplied_by'];
			$phone_no = $_POST['phone_no'];
			$purch_location = $_POST['purch_location'];
			$purch_product = $_POST['purch_product'];
			$purch_amount = $_POST['purch_amount'];
			$purch_gram = $_POST['purch_gram'];
			$purch_gram_both = $_POST['purch_gram_both'];
			$purch_water = $_POST['purch_water'];
			$purch_price = $_POST['purch_price'];
			$purch_pounds = $_POST['purch_pounds'];
			$purch_density = $_POST['purch_density'];
			$purch_karat = $_POST['purch_karat'];
			$purch_purity = $_POST['purch_purity'];
			$purch_ppp = $_POST['purch_ppp'];
			$purch_pieces = $_POST['purch_pieces'];
			$purch_narration = addslashes($_POST['purch_narration']);
			
			$method = $_POST['purch_method'];
			$purity_discount = $_POST['purch_purity_discount'];
			$discounted_karat = $_POST['purch_discounted_karat'];
			$discounted_purity = $_POST['purch_discounted_purity'];
			$discounted_ppp = $_POST['purch_discounted_ppp'];
			$discounted_amount = $_POST['purch_discounted_amount'];

			$query = "UPDATE `purchases`SET `company_id`='$company_id',`user_super_id`='$user_super_id',
			`user_id`='$user_id',`date`='$purch_date', `ledger_debit`='$purch_debit', `ledger_credit`='$purch_credit', 
			`amount`='$purch_amount', `phone`='$phone_no', `supplier`='$purch_supplied_by', `location`='$purch_location', 
			`narration`='$purch_narration',`product_id`='$purch_product', `weight`='$purch_gram',`weight_both`='$purch_gram_both', 
			`water`='$purch_water', `density`='$purch_density', `pounds`='$purch_pounds', `karat`='$purch_karat',
			`price`='$purch_price', `purity`='$purch_purity', `price_per_pound`='$purch_ppp', `method`='$method', 
			`purity_discount`='$purity_discount', `discounted_karat`='$discounted_karat',`discounted_purity`='$discounted_purity', 
			`discounted_ppp`='$discounted_ppp', `discounted_amount`='$discounted_amount',`pieces`='$purch_pieces', 
			`site_id`='$site_id', `branch_id`='$branch_id' WHERE `purchase_id`='$purchase_id'";
	    	$query_run = mysqli_query($con, $query);

	    	if ($query_run) {
	    		//POST TRANSACTION
		    	if(isset($purchase_id) && $purchase_id > 0)
				{
					$query_trans_del = "DELETE FROM `transactions` WHERE `purchase_id`='$purchase_id'";
					mysqli_query($con, $query_trans_del);

					$query_dr = "INSERT INTO `transactions`(
					`company_id`,`user_id`,`purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
					'$company_id','$user_id','$purchase_id','$purch_debit','$purch_credit','$purch_date','$discounted_amount','$discounted_amount','$purch_narration')";
					mysqli_query($con, $query_dr);

					$query_cr = "INSERT INTO `transactions`(
					`company_id`,`user_id`,`purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
					'$company_id','$user_id','$purchase_id','$purch_credit','$purch_debit','$purch_date','$discounted_amount','$discounted_amount','$purch_narration')";
					mysqli_query($con, $query_cr);
					
					$query_site = "DELETE FROM `site_revenue` WHERE `purchase_id`='$purchase_id'";
					mysqli_query($con,$query_site);

					$query = "INSERT INTO `site_revenue`(
					`site_id`,`company_id`,`user_super_id`,`user_id`,`purchase_id`, `date`, `amount`, `narration`) VALUES (
					'$site_id','$company_id','$user_super_id','$user_id','$purchase_id','$purch_date','$discounted_amount','$purch_narration')";
					mysqli_query($con, $query);
					
					$_SESSION['purch_display_company_id'] = $company_id;
					$_SESSION['purch_display_user_id'] = $user_id;
					$_SESSION['purch_display_user_super_id'] = $user_super_id;
					$_SESSION['purch_display_purchase_id'] = $purchase_id;
					$_SESSION['purch_display_ledger_credit_id'] = $purch_credit;

					echo "Purchase saved Successfully";
				};
	    	}  
			else  
			{  
			  echo "Purchase NOT saved";  
			};
		}

