		function send_sms_purchase_invoice()
		{
			global $con;
			$purchase_id = $_POST['purchase_id'];
			$query = "SELECT * FROM purchases WHERE purchase_id='$purchase_id'";
			$result = mysqli_query($con,$query);
			while($row = mysqli_fetch_assoc($result))
			{
				$company_id = $row['company_id'];
				$telephone = $row['phone'];
				$sql_company = "SELECT * FROM company WHERE company_id = '$company_id' ORDER BY trading_name ASC";
				$result_company = mysqli_query($con,$sql_company);
				$row_company = mysqli_fetch_array($result_company);
				$amount = $row['amount'];
				$amount_purchase = number_format($amount, 2, '.', ',');


				$query_sms = "SELECT SUM(qty_purchased) AS qty_in, SUM(qty_sent) AS qty_out FROM sms WHERE company_id='$company_id'";
				$result_sms = mysqli_query($con,$query_sms);
				if(!empty($result_sms) && mysqli_num_rows($result_sms) > 0)
				{
					$row_sms = mysqli_fetch_assoc($result_sms);
					$sms_bal = $row_sms['qty_in'] - $row_sms['qty_out'];
				}
				else
				{
					$sms_bal = 0;
				};
				
				if($sms_bal > 0)
				{
					$message = nl2br ($row_company['trading_name']."\n".$row_company['telephone']."\n
					Date:".$row['date']."\n
					Customer:".$row['supplier']."\n
					Tel:".$row['phone']."\n
					Top:".$row['weight']."\n
					Down:".$row['water']."\n
					Price:".$row['price']."\n
					Amount:".$row_company['currency'].''.$amount_purchase."\n\n
					Thanks for doing business with us!");
					
					$received_from = $row['supplier'].';'.$telephone;
					$user_id = $_SESSION['user_id'];
					$date = date('Y-m-d');
					$phone = substr($telephone, 1, 9);
					$to = '233'.$phone;		
					if($telephone !='' && strlen($telephone) > 9)
					{
						sendSMS($to, $message);
						$query_msg = "INSERT INTO `sms`(`date`,`qty_sent`,`name`,`company_id`,`created_by`,
						`created_datetime`) VALUES ('$date',1,'$received_from','$company_id','$user_id',NOW())";
						mysqli_query($con,$query_msg);
					};
				};
			};
			//echo $message;
		}
		

