		function save_bulk_purchase_invoice()
		{
			global $con;
			$bulk_purchase_id = $_POST['bulk_purchase_id'];
			$purch_debit = $_POST['bulk_purch_debit'];
			$purch_credit = $_POST['bulk_purch_credit'];
			$purch_date = $_POST['bulk_purch_date'];
			$purch_supplied_by = $_POST['bulk_purch_supplied_by'];
			$purch_phone_no = $_POST['bulk_purch_phone_no'];
			$purch_location = $_POST['bulk_purch_location'];
			$purch_narration = addslashes($_POST['bulk_purch_narration']);
			$p_grams_total = $_POST['p_grams_total'];
			$p_water_total = $_POST['p_water_total'];
			$p_pounds_total = $_POST['p_pounds_total'];
			$p_amount_total = $_POST['p_amount_total'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			
			if($company_id > 0)
			{
				$query_last_sno = "SELECT `sno` FROM `bulk_purchases` WHERE 
				`company_id` = '$company_id' ORDER BY `sno` DESC";
				$result_last_sno = mysqli_query($con,$query_last_sno);
				if(!empty($result_last_sno) && mysqli_num_rows($result_last_sno) > 0)
				{
					$row_last_sno = mysqli_fetch_assoc($result_last_sno);
					$last_sno = $row_last_sno['sno'];
					$next_sno = $last_sno + 1;
				}
				else
				{
					$next_sno = 1;
				};

				$query = "INSERT INTO `bulk_purchases`(
				`sno`,`company_id`,`user_super_id`,`user_id`,`date`, `ledger_debit`, `ledger_credit`, 
				`amount`, `phone`, `supplier`, `location`, `narration`, `total_weight`,`total_water`, 
				`total_pounds`, `total_amount`, `branch_id`, `created_by`, `created_datetime`) 
				VALUES (
				'$next_sno','$company_id','$user_id','$user_id','$purch_date','$purch_debit',
				'$purch_credit','$p_amount_total','$purch_phone_no','$purch_supplied_by','$purch_location',
				'$purch_narration','$p_grams_total','$p_water_total','$p_pounds_total','$p_amount_total',
				'$branch_id','$user_id',NOW())";
				$query_run = mysqli_query($con, $query);
				
				if ($query_run) 
				{
					$query = "SELECT * FROM bulk_purchases ORDER BY bulk_purchase_id DESC";
					$result = mysqli_query($con,$query);
					if(!empty($result) && mysqli_num_rows($result) > 0)
					{
						$row = mysqli_fetch_assoc($result);
						$bulk_purchase_id = $row['bulk_purchase_id'];
						$_SESSION['bulk_purchase_id'] = $row['bulk_purchase_id'];
					}
					else
					{
						$bulk_purchase_id = 0;
						$_SESSION['bulk_purchase_id'] = '';
					};

					//PURCHASE INVOICE
					$number_as = count($_POST["bulk_purch_gram_both_t"]);  
					if($number_as > 0)
					{  
						for($i = 0; $i < $number_as; $i++)  
						{  
							if(trim($_POST["bulk_purch_gram_both_t"][$i] != '') && trim($_POST["bulk_purch_gram_both_t"][$i] != 0))  
							{  
								$purch_product = $_POST['bulk_purch_product_t'][$i];
								$purch_gram_both = $_POST['bulk_purch_gram_both_t'][$i];
								$purch_gram = $_POST['bulk_purch_gram_t'][$i];
								$purch_water = $_POST['bulk_purch_water_t'][$i];
								$purch_density = $_POST['bulk_purch_density_t'][$i];
								$purch_karat = $_POST['bulk_purch_karat_t'][$i];
								$purch_purity = $_POST['bulk_purch_purity_t'][$i];
								$purch_pounds = $_POST['bulk_purch_pounds_t'][$i];
								$purch_ppp = $_POST['bulk_purch_ppp_t'][$i];
								$purch_price = $_POST['bulk_purch_price_t'][$i];
								$purch_amount = $_POST['bulk_purch_amount_t'][$i];
								$purch_pieces = $_POST['bulk_purch_pieces_t'][$i];
								
								$query_last_sno = "SELECT `sno` FROM `purchases` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
								$result_last_sno = mysqli_query($con,$query_last_sno);
								if(!empty($result_last_sno) && mysqli_num_rows($result_last_sno) > 0)
								{
									$row_last_sno = mysqli_fetch_assoc($result_last_sno);
									$last_sno = $row_last_sno['sno'];
									$next_sno = $last_sno + 1;
								}
								else
								{
									$next_sno = 1;
								};

								$query = "INSERT INTO `purchases`(
								`sno`,`company_id`,`user_super_id`,`user_id`,`date`, `ledger_debit`, `ledger_credit`, 
								`amount`, `phone`, `supplier`, `location`, `narration`, `weight_both`,`product_id`, 
								`weight`, `water`, `density`, `pounds`, `karat`, `price`, `purity`, `price_per_pound`, 
								`pieces`, `branch_id`, `created_by`, `created_datetime`, `bulk_purchase_id`) 
								VALUES (
								'$next_sno','$company_id','$user_id','$user_id','$purch_date','$purch_debit',
								'$purch_credit','$purch_amount','$purch_phone_no','$purch_supplied_by','$purch_location',
								'$purch_narration','$purch_gram_both','$purch_product','$purch_gram','$purch_water',
								'$purch_density','$purch_pounds','$purch_karat','$purch_price','$purch_purity',
								'$purch_ppp','$purch_pieces','$branch_id','$user_id',NOW(),'$bulk_purchase_id')";
								$query_run = mysqli_query($con, $query);
								
								if ($query_run) 
								{
									//POST TRANSACTION
									$query = "SELECT * FROM purchases ORDER BY purchase_id DESC";
									$result = mysqli_query($con,$query);
									if(!empty($result) && mysqli_num_rows($result) > 0)
									{
										$row = mysqli_fetch_assoc($result);
										$purchase_id = $row['purchase_id'];
									}
									else
									{
										$purchase_id = 0;
									};

									$query_dr = "INSERT INTO `transactions`(
									`company_id`,`user_super_id`,`user_id`,`purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, 
									`amount`, `amount_debit`, `narration`, `created_by`, `created_datetime`, `bulk_purchase_id`) VALUES (
									'$company_id','$user_id','$user_id','$purchase_id','$purch_debit','$purch_credit',
									'$purch_date','$purch_amount','$purch_amount','$purch_narration','$user_id', NOW(),'$bulk_purchase_id')";
									mysqli_query($con, $query_dr);

									$query_cr = "INSERT INTO `transactions`(
									`company_id`,`user_super_id`,`user_id`,`purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, 
									`amount`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_purchase_id`) VALUES (
									'$company_id','$user_id','$user_id','$purchase_id','$purch_credit','$purch_debit',
									'$purch_date','$purch_amount','$purch_amount','$purch_narration','$user_id', NOW(),'$bulk_purchase_id')";
									mysqli_query($con, $query_cr);
								};
							}; 
						};
					};

					//DIRECT PAYMENTS
					$number_ledger = count($_POST["bulk_purchase_payment_amount"]);  
					if($number_ledger > 0)  
					{  
						for($i = 0; $i < $number_ledger; $i++)  
						{  
							if(trim($_POST["bulk_purchase_payment_amount"][$i] != ''))
							{  
								$ledger_id = trim($_POST['bulk_purchase_payment_ledger_id'][$i]);
								$group_id = trim($_POST['bulk_purchase_payment_ledger_group_id'][$i]);
								$mode = trim($_POST['bulk_purchase_payment_mode'][$i]);
								$amount = trim($_POST['bulk_purchase_payment_amount'][$i]);

								if($group_id != 6)
								{
									$query_last_sno = "SELECT `sno` FROM `journal` WHERE `company_id` = '$company_id' 
									ORDER BY `sno` DESC";
									$result_last_sno = mysqli_query($con,$query_last_sno);
									if (mysqli_num_rows($result_last_sno) > 0)
									{
										$row_last_sno = mysqli_fetch_assoc($result_last_sno);
										$last_sno = $row_last_sno['sno'];
										$next_sno = $last_sno + 1;
									}
									else
									{
										$next_sno = 1;
									};

									$query_journal = "INSERT INTO `journal`(
									`sno`, `company_id`, `user_id`, `reference_no`, `narration`,  `bulk_purchase_id`, `mode`, 
									`ledger_debit`, `ledger_credit`, `amount`, `date`, `branch_id`, `created_by`, `created_datetime`) VALUES (
									'$next_sno','$company_id','$user_id','$bulk_purchase_id','$purch_narration','$bulk_purchase_id','$mode',
									'$purch_credit','$ledger_id','$amount','$purch_date','$branch_id','$user_id',NOW())";
									$query_run_journal = mysqli_query($con, $query_journal);
									
									if ($query_run_journal) 
									{
										//POST TRANSACTION
											$query = "SELECT * FROM journal WHERE `company_id`='$company_id' ORDER BY journal_id DESC";
											$result = mysqli_query($con,$query);
											$row = mysqli_fetch_assoc($result);
											$journal_id = $row['journal_id'];
											
											$query_dr = "INSERT INTO `transactions`(
											`journal_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
											`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_purchase_id`) VALUES (
											'$journal_id','$purch_credit','$ledger_id','$company_id','$user_id','$purch_date',
											'$amount','$amount',0,'$purch_narration','$user_id',NOW(),'$bulk_purchase_id')";
											mysqli_query($con, $query_dr);

											$query_cr = "INSERT INTO `transactions`(
											`journal_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
											`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_purchase_id`) VALUES (
											'$journal_id','$ledger_id','$purch_credit','$company_id','$user_id','$purch_date',
											'$amount',0,'$amount','$purch_narration','$user_id',NOW(),'$bulk_purchase_id')";
											mysqli_query($con, $query_cr);
									};
								}
								else
								{
									$query_last_sno = "SELECT `sno` FROM `payment` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
									$result_last_sno = mysqli_query($con,$query_last_sno);
									if(!empty($result_last_sno) && mysqli_num_rows($result_last_sno) > 0)
									{
										$row_last_sno = mysqli_fetch_assoc($result_last_sno);
										$last_sno = $row_last_sno['sno'];
										$next_sno = $last_sno + 1;
									}
									else
									{
										$next_sno = 1;
									};

									$query = "INSERT INTO `payment`(
									`sno`,`company_id`, `user_id`, `user_super_id`, `ledger_credit`, `date`, `amount`, `narration`, 
									`mode`, `payee`,`branch_id`,`bulk_purchase_id`) VALUES ('$next_sno',
									'$company_id','$user_id','$user_id','$ledger_id','$purch_date','$amount',
									'$purch_narration','$mode','$purch_supplied_by','$branch_id','$bulk_purchase_id')";
									$query_run = mysqli_query($con, $query);
									if ($query_run) 
									{
										//POST TRANSACTION
										$query = "SELECT * FROM payment WHERE `company_id`='$company_id' ORDER BY payment_id DESC";
										$result = mysqli_query($con,$query);

										if(!empty($result) && mysqli_num_rows($result) > 0)
										{
											$row = mysqli_fetch_assoc($result);
											$payment_id = $row['payment_id'];
										}
										else
										{
											$payment_id = 0;
										};

										//PAYMENT_ITEMS
										$query_dr = "INSERT INTO `transactions`(
										`payment_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, 
										`date`, `amount`, `amount_debit`, `amount_credit`, `narration`,`bulk_purchase_id`, 
										`created_by`, `created_datetime`) VALUES (
										'$payment_id','$purch_credit','$ledger_id','$company_id','$user_id','$user_id','$purch_date',
										'$amount','$amount',0,'$purch_narration','$bulk_purchase_id','$user_id',NOW())";
										mysqli_query($con, $query_dr);

										$query_cr = "INSERT INTO `transactions`(
										`payment_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, 
										`date`, `amount`, `amount_debit`, `amount_credit`, `narration`, `bulk_purchase_id`, 
										`created_by`, `created_datetime`) VALUES (
										'$payment_id','$ledger_id','$purch_credit','$company_id','$user_id','$user_id','$purch_date',
										'$amount',0,'$amount','$purch_narration','$bulk_purchase_id','$user_id',NOW())";
										mysqli_query($con, $query_cr);
									};
								};
							};
						};
					};
				}
				else
				{
					echo 'not_entered';
				};
			};
		}

		function bulk_purchase_set_supplied_by()
		{
			global $con;
