		function edit_bulk_purchase_invoice()
		{
			global $con;
			$bulk_purchase_id = $_POST['bulk_purchase_id'];
			$bulk_purchases = array();
			$payment = array();
			$details = array();
			$query = "SELECT * FROM bulk_purchases WHERE bulk_purchase_id='$bulk_purchase_id'";
			$result = mysqli_query($con,$query);
			while($row = mysqli_fetch_assoc($result))
			{
				array_push($bulk_purchases, 
					$row['bulk_purchase_id'],$row['date'],$row['ledger_debit'],$row['ledger_credit'],$row['amount'],
					$row['supplier'],$row['phone'],$row['narration'],$row['location']
				);
			}
			$query = "SELECT * FROM purchases WHERE bulk_purchase_id='$bulk_purchase_id'";
			$result = mysqli_query($con,$query);
			$i = 1;
