			while($row = mysqli_fetch_assoc($result))
			{
				$i++;
				$bulk_purch_product = $row['product_id'];
				$bulk_purch_gram_both = $row['weight_both'];
				$bulk_purch_gram = $row['weight'];
				$bulk_purch_water = $row['water'];
				$bulk_purch_price = $row['price'];
				$bulk_purch_amount = $row['amount'];
