				$bulk_purch_karat = $row['karat'];
				$bulk_purch_purity = $row['purity'];
				$bulk_purch_ppp = $row['price_per_pound'];
				$bulk_purch_pieces = $row['pieces'];
				$bulk_purch_price_f = number_format($bulk_purch_price, 2, '.', ',');
				$bulk_purch_amount_f = number_format($bulk_purch_amount, 2, '.', ',');
				$value .= '<tr id="'.$i.'">
					<td class = "action-td" width="5%">
						'.$bulk_purch_pieces.'
