						if($i > 1)
						{
							$payment .= '<a href="#" class="btn_delete_bulk_purchase_payment_ledger" id="btn_delete_bulk_purchase_payment_ledger'.$i.'" data-id="'.$i.'"><i class="fa fa-trash fa-sm"></i></a>';
						};
						$payment .= '</td>
					</tr>';
					$total_paid = $total_paid + $row_payment['amount'];
				};
			};
			array_push($details, $bulk_purchases, $value, $payment, $total_paid);
			echo json_encode($details);
		}

		function update_bulk_purchase_invoice()
