												$row = mysqli_fetch_assoc($result);
												$journal_id = $row['journal_id'];
												
												$query_dr = "INSERT INTO `transactions`(
												`journal_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
