												'$amount','$amount',0,'$purch_narration','$user_id',NOW(),'$bulk_purchase_id')";
												mysqli_query($con, $query_dr);

												$query_cr = "INSERT INTO `transactions`(
												`journal_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
												`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_purchase_id`) VALUES (
												'$journal_id','$ledger_id','$purch_credit','$company_id','$user_id','$purch_date',
												'$amount',0,'$amount','$purch_narration','$user_id',NOW(),'$bulk_purchase_id')";
												mysqli_query($con, $query_cr);
