												><i class="fa fa-print fa-sm"></i></a>';
										
										if ($_SESSION['user_type'] == 'Ultra_Super_User' OR $_SESSION['user_type'] == 'Super_User' OR ($_SESSION['user_type'] == 'Normal_User' AND $_SESSION['Delete_Purchases'] == 'Yes')) 
