		function save_stock_purchase_invoice()
		{
			global $con;
			$purch_debit = $_POST['stock_purch_debit'];
			$purch_credit = $_POST['stock_purch_credit'];
			$branch_id = $_SESSION['branch_id'];
			$purch_amount = $_POST['stock_purch_amount'];
			$purch_supplied_by = $_POST['stock_purch_supplied_by'];
			$purch_ref_no = $_POST['stock_purch_ref_no'];
			$purch_date = $_POST['stock_purch_date'];
			$purch_received_by = $_POST['stock_purch_received_by'];
			$purch_narration = $_POST['stock_purch_narration'];
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];


			$unique = $_POST['stock_purchase_unique'];
			$query_uniq = "SELECT * FROM stock_purchases WHERE stock_purchases_unique = '$unique'";
			$result_uniq = mysqli_query($con,$query_uniq);
			if(!empty($result_uniq) && mysqli_num_rows($result_uniq) > 0)
			{
				echo 'exist';
			}
			else
			{
				if($company_id > 0)
				{
					$query = "SELECT sno FROM stock_purchases WHERE company_id = '$company_id' ORDER BY sno DESC";
					$result = mysqli_query($con,$query);
					$row = mysqli_fetch_assoc($result);
					$sno = $row['sno'] + 1;

					$query = "INSERT INTO `stock_purchases`(
					`company_id`, `date`, `ledger_debit`, `ledger_credit`, `amount`, `reference_no`, 
					`supplied_by`, `received_by`, `narration`, `sno`, `branch_id`, `created_by`, `created_datetime`) 
					VALUES ('$company_id','$purch_date','$purch_debit','$purch_credit','$purch_amount',
					'$purch_ref_no','$purch_supplied_by',
					'$purch_received_by','$purch_narration','$sno','$branch_id','$user_id',NOW())";
					$query_run = mysqli_query($con, $query);

					if ($query_run) 
					{
						//POST TRANSACTION
							$query = "SELECT * FROM stock_purchases ORDER BY stock_purchase_id DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);
							$stock_purchase_id = $row['stock_purchase_id'];

							$query_dr = "INSERT INTO `transactions`(
							`company_id`, `branch_id`,`stock_purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
							'$company_id','$branch_id','$stock_purchase_id','$purch_debit','$purch_credit','$purch_date','$purch_amount','$purch_amount','$purch_narration')";
							mysqli_query($con, $query_dr);

							$query_cr = "INSERT INTO `transactions`(
							`company_id`, `branch_id`,`stock_purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
							'$company_id','$branch_id','$stock_purchase_id','$purch_credit','$purch_debit','$purch_date','$purch_amount','$purch_amount','$purch_narration')";
							mysqli_query($con, $query_cr);

							$number_as = count($_POST["stock_purch_desc"]);  
							if($number_as > 0)  
							{  
								for($i=0; $i<$number_as; $i++)  
								{  
									if(trim($_POST["stock_purch_desc"][$i] !== '') && trim($_POST["stock_purch_desc"][$i] !== 0))  
									{  
											$purch_desc = $_POST['stock_purch_desc'][$i];
											$purch_loc = $_POST['stock_purch_loc'][$i];
											$purch_qty = $_POST['stock_purch_qty'][$i];
											$purch_price = $_POST['stock_purch_price'][$i];
											$purch_amt = $_POST['stock_purch_amt'][$i];
											$purch_batch = $_POST['stock_purch_batch'][$i];
											$purch_expiry_date = $_POST['stock_purch_expiry_date'][$i];
											$query = "INSERT INTO `stock_purchase_items`
											(`company_id`, `stock_purchase_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, `amount`, `batch`, `expiry_date`, `qty`) VALUES 
											('$company_id','$stock_purchase_id','$purch_desc','$purch_loc','$purch_date','$purch_price','$purch_amt','$purch_batch',
											'$purch_expiry_date','$purch_qty')";
											$query_run = mysqli_query($con, $query);
									}  
								}
								echo "saved";
							}  
							else  
							{  
								echo "no_item";  
							};
					} 
					else  
					{  
						echo "error";  
					};
				}
				else
				{
					echo 'no_company';
				};
			};
		}

