	    function update_stock_purchase_invoice()
		{
			global $con;
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			$stock_purchase_id = $_POST['stock_purchase_id'];
			$branch_id = $_POST['stock_purchase_branch_id'];
			$purch_debit = $_POST['stock_purch_debit'];
			$purch_credit = $_POST['stock_purch_credit'];
			$purch_amount = $_POST['stock_purch_amount'];
			$purch_supplied_by = $_POST['stock_purch_supplied_by'];
			$purch_ref_no = $_POST['stock_purch_ref_no'];
			$purch_date = $_POST['stock_purch_date'];
			$purch_received_by = $_POST['stock_purch_received_by'];
			$purch_narration = $_POST['stock_purch_narration'];
			$userdetail = $_SESSION['full_name'].':-'.time();

			if($company_id > 0)
			{
				$query = "UPDATE `stock_purchases` SET `date`='$purch_date',`ledger_debit`='$purch_debit',
				`ledger_credit`='$purch_credit',`amount`='$purch_amount',`reference_no`='$purch_ref_no',`branch_id`='$branch_id',
				`supplied_by`='$purch_supplied_by',`received_by`='$purch_received_by',`branch_id`='$branch_id',
				`narration`='$purch_narration',`altered_by`='$user_id',`altered_datetime`=NOW() WHERE `stock_purchase_id`='$stock_purchase_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					if(isset($stock_purchase_id) && $stock_purchase_id > 0)
					{
						//POST TRANSACTION
						$query_trans_del = "DELETE FROM `transactions` WHERE `stock_purchase_id`='$stock_purchase_id'";
						mysqli_query($con, $query_trans_del);

						$query_dr = "INSERT INTO `transactions`(
						`company_id`, `branch_id`,`stock_purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
						'$company_id','$branch_id','$stock_purchase_id','$purch_debit','$purch_credit','$purch_date','$purch_amount','$purch_amount','$purch_narration')";
						mysqli_query($con, $query_dr);

						$query_cr = "INSERT INTO `transactions`(
						`company_id`, `branch_id`,`stock_purchase_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
						'$company_id','$branch_id','$stock_purchase_id','$purch_credit','$purch_debit','$purch_date','$purch_amount','$purch_amount','$purch_narration')";
						mysqli_query($con, $query_cr);


						$query = "UPDATE `stock_purchase_items` SET `status`='' WHERE `stock_purchase_id`='$stock_purchase_id'";
						mysqli_query($con,$query);

						$number_pi = count($_POST["stock_purch_desc"]);
						if($number_pi > 0)  
						{  
							for($i=0; $i<$number_pi; $i++)  
							{  
								if(trim($_POST["stock_purch_desc"][$i] !== '') && trim($_POST["stock_purch_desc"][$i] !== 0))  
								{  
									$purch_item_list_id = $_POST['stock_purch_item_list_id'][$i];
									$purch_desc = $_POST['stock_purch_desc'][$i];
									$purch_loc = $_POST['stock_purch_loc'][$i];
									$purch_qty = $_POST['stock_purch_qty'][$i];
									$purch_price = $_POST['stock_purch_price'][$i];
									$purch_amt = $_POST['stock_purch_amt'][$i];
									$purch_batch = $_POST['stock_purch_batch'][$i];
									$purch_expiry_date = $_POST['stock_purch_expiry_date'][$i];
									//$purch_cat_id = $_POST['purch_cat_id'][$i];

									if($purch_item_list_id !== "" && $purch_item_list_id !== 0)
									{
										$query = "UPDATE `stock_purchase_items` SET `stock_purchase_id`='$stock_purchase_id', `stock_item_id`='$purch_desc', 
										`warehouse_id`='$purch_loc', `date`='$purch_date', `price`='$purch_price', `amount`='$purch_amt', `batch`='$purch_batch', 
										`expiry_date`='$purch_expiry_date', `qty`='$purch_qty',`status`='updated' WHERE `purch_item_id`='$purch_item_list_id'";
									}
									else
									{
										$query = "INSERT INTO `stock_purchase_items`(`company_id`,`stock_purchase_id`, `stock_item_id`, `warehouse_id`, 
										`date`, `price`, `amount`, `batch`,
										`expiry_date`, `qty`,`status`) VALUES ('$company_id','$stock_purchase_id','$purch_desc','$purch_loc','$purch_date','$purch_price',
										'$purch_amt','$purch_batch','$purch_expiry_date','$purch_qty','updated')";
									};

									mysqli_query($con, $query);
								};
							};

							$query = "DELETE FROM `stock_purchase_items` WHERE `status`='' AND `stock_purchase_id`='$stock_purchase_id'";
							mysqli_query($con,$query);

							echo "Stock Purchase Updated";
						}  
						else  
						{  
