	//HIRING
		function hiring_start_end()
		{
			global $con;
			$entry_type = $_POST['entry_type'];
			$i = $_POST['i'];
			$data = array();
			if($entry_type == 'Real_Time')
			{
				$start = '<input type="time" name="hiring_start[]" class="form-control bg-light hiring_start" id="hiring_start'.$i.'" data-id="'.$i.'" style="border-width:0px">';
				$end = '<input type="time" name="hiring_end[]" class="form-control bg-light hiring_end" id="hiring_end'.$i.'" data-id="'.$i.'" style="border-width:0px">';
			}
			else if($entry_type == 'Meter_Reading')
			{
				$start = '<input type="text" name="hiring_start[]" class="form-control bg-light hiring_start" id="hiring_start'.$i.'" data-id="'.$i.'" style="border-width:0px">';
				$end = '<input type="text" name="hiring_end[]" class="form-control bg-light hiring_end" id="hiring_end'.$i.'" data-id="'.$i.'" style="border-width:0px">';
			};
			
			array_push($data, $start, $end);
			echo json_encode($data);
		}

		function hiring_get_hours()
		{
			global $con;
			$asset_id = $_POST['asset_id'];
			$start = $_POST['start'];
			$end = $_POST['end'];
			$entry_type = $_POST['entry_type'];
			$company_id = $_SESSION['company_id'];
			$data = array();
			if($entry_type == 'Real_Time')
			{
				if($start !='' && $end !='')
				{
					$start_time = strtotime($start);
					$end_time = strtotime($end);
					$hours = floor((($end_time- $start_time)/60)/60); 
					$hours_in_seconds = $hours*3600; 
					$time_in_seconds = $end_time - $start_time;
					$duration = $hours.':'.($time_in_seconds - $hours_in_seconds)/60;
					$actual_hours = $hours.'.'.floor(((($time_in_seconds - $hours_in_seconds)/60)/60)*100);
				};
			}
			else if($entry_type == 'Meter_Reading')
			{
				if($start > 0 && $end > 0)
				{
					$duration = $end - $start;
					$actual_hours = $end - $start;
				};
			};
			
			$query = "SELECT COUNT(hiring_id) AS invoices FROM hiring_list WHERE asset_id = '$asset_id' AND end > '$start' AND 
			company_id = '$company_id'";
            $query_run = mysqli_query($con, $query);
			if (mysqli_num_rows($query_run) > 0)
			{
				$row = mysqli_fetch_assoc($query_run);
				$occurance = $row['invoices'];
			}
			else
			{
				$occurance = 0;
			};
				
			
			array_push($data, $duration, $actual_hours, $occurance);
			echo json_encode($data);
		}

