		function save_hiring_invoice()
		{
			global $con;
			$hiring_debit = $_POST['hiring_debit'];
			$hiring_credit = $_POST['hiring_credit'];
			$hiring_amount = $_POST['hiring_amount'];
			$hiring_by = $_POST['hiring_by'];
			$hiring_address = $_POST['hiring_address'];
			$hiring_date = $_POST['hiring_date'];
			$hiring_phone = $_POST['hiring_phone'];
			$hiring_narration = $_POST['hiring_narration'];
			$hiring_operator = $_POST['hiring_operator'];
			$hiring_foreman = $_POST['hiring_foreman'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];

			if($company_id > 0)
			{
				$query = "SELECT sno FROM hiring WHERE company_id = '$company_id' ORDER BY sno DESC";
				$result = mysqli_query($con,$query);
				$row = mysqli_fetch_assoc($result);
				if(isset($row)){$sno = $row['sno'] + 1;}else{$sno = 1;}

				$query = "INSERT INTO `hiring`(
				`company_id`, `date`, `ledger_debit`, `ledger_credit`, `amount`, `hired_by`, 
				`address`, `telephone`, `narration`, `sno`, `status`, `branch_id`, `operator`, `foreman`) 
				VALUES ('$company_id','$hiring_date','$hiring_debit','$hiring_credit','$hiring_amount',
				'$hiring_by','$hiring_address',
				'$hiring_phone','$hiring_narration','$sno','Active','$branch_id','$hiring_operator','$hiring_foreman')";
		    	$query_run = mysqli_query($con, $query);

		    	if ($query_run) 
		    	{
		    		//POST TRANSACTION
			    		$query = "SELECT * FROM hiring ORDER BY hiring_id DESC";
						$result = mysqli_query($con,$query);
						$row = mysqli_fetch_assoc($result);
						$hiring_id = $row['hiring_id'];
						$_SESSION['hiring_id'] = $row['hiring_id'];

			    		$query_dr = "INSERT INTO `transactions`(
		                `company_id`,`hiring_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
		                '$company_id','$hiring_id','$hiring_debit','$hiring_credit','$hiring_date','$hiring_amount','$hiring_amount','$hiring_narration')";
		                mysqli_query($con, $query_dr);

		                $query_cr = "INSERT INTO `transactions`(
		                `company_id`,`hiring_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
		                '$company_id','$hiring_id','$hiring_credit','$hiring_debit','$hiring_date','$hiring_amount','$hiring_amount','$hiring_narration')";
		                mysqli_query($con, $query_cr);

		    			$number_as = count($_POST["hiring_asset_id"]);  
						if($number_as > 0)  
						{  
						  for($i=0; $i<$number_as; $i++)  
						  {  
						       if(trim($_POST["hiring_asset_id"][$i] !== '') && trim($_POST["hiring_asset_id"][$i] !== 0))  
						       {  
