		function edit_hiring_invoice()
		{
			global $con;
			$hiring_id = $_POST['hiring_id'];
			$data=array();
			$query = "SELECT * FROM hiring WHERE hiring_id='$hiring_id'";
			$result = mysqli_query($con,$query);
			while($row=mysqli_fetch_assoc($result))
			{
				array_push($data, 
					$row['hiring_id'],$row['date'],$row['ledger_debit'],$row['ledger_credit'],
					$row['amount'],$row['hired_by'],
					$row['address'],$row['telephone'],$row['narration'],$row['branch_id'],
					$row['operator'], $row['foreman']
				);
			}
			 echo json_encode($data);
		}

