	    function update_hiring_invoice()
		{
			global $con;
			$hiring_id = $_POST['hiring_id'];
			$branch_id = $_POST['hiring_branch_id'];
			$hiring_debit = $_POST['hiring_debit'];
			$hiring_credit = $_POST['hiring_credit'];
			$hiring_amount = $_POST['hiring_amount'];
			$hiring_by = $_POST['hiring_by'];
			$hiring_address = $_POST['hiring_address'];
			$hiring_date = $_POST['hiring_date'];
			$hiring_phone = $_POST['hiring_phone'];
			$hiring_narration = $_POST['hiring_narration'];
			$hiring_operator = $_POST['hiring_operator'];
			$hiring_foreman = $_POST['hiring_foreman'];
			$company_id = $_SESSION['company_id'];
			$userdetail = $_SESSION['full_name'].':-'.time();

			if($company_id > 0)
			{
				$query = "UPDATE `hiring`SET
				`date`='$hiring_date', `ledger_debit`='$hiring_debit', `ledger_credit`='$hiring_credit', 
				`amount`='$hiring_amount', `operator`='$hiring_operator',`foreman`='$hiring_foreman',
				`hired_by`='$hiring_by', `address`='$hiring_address', `telephone`='$hiring_phone', 
				`narration`='$hiring_narration',`branch_id`='$branch_id'
				WHERE `hiring_id`='$hiring_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					//POST TRANSACTION
					if(isset($hiring_id) && $hiring_id > 0)
					{
						$query = "DELETE FROM `transactions` WHERE hiring_id='$hiring_id'";
						mysqli_query($con,$query);

						$query_dr = "INSERT INTO `transactions`(
						`company_id`,`hiring_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
						'$company_id','$hiring_id','$hiring_debit','$hiring_credit','$hiring_date','$hiring_amount','$hiring_amount','$hiring_narration')";
						mysqli_query($con, $query_dr);

						$query_cr = "INSERT INTO `transactions`(
						`company_id`,`hiring_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
						'$company_id','$hiring_id','$hiring_credit','$hiring_debit','$hiring_date','$hiring_amount','$hiring_amount','$hiring_narration')";
						mysqli_query($con, $query_cr);

						$query = "UPDATE `hiring_list` SET `status`='' WHERE `hiring_id`='$hiring_id'";
						$result = mysqli_query($con,$query);

						$number_as = count($_POST["hiring_asset_id"]);  
						if($number_as > 0)  
						{  
							for($i=0; $i<$number_as; $i++)  
							{  
								if(trim($_POST["hiring_asset_id"][$i] !== '') && trim($_POST["hiring_asset_id"][$i] !== 0))  
								{  
									$hiring_item_list_id = $_POST['hiring_item_list_id'][$i];
									$hiring_asset_id = $_POST['hiring_asset_id'][$i];
									$hiring_site_id = $_POST['hiring_site_id'][$i];
									$hiring_time_entry_type = $_POST['hiring_time_entry_type'][$i];
									$hiring_start = $_POST['hiring_start'][$i];
									$hiring_end = $_POST['hiring_end'][$i];
									$hiring_hour = $_POST['hiring_hour'][$i];
									$hiring_rate = $_POST['hiring_rate'][$i];
									$hiring_amt = $_POST['hiring_amt'][$i];
									$hiring_remark = $_POST['hiring_remark'][$i];

									if($hiring_item_list_id !== "" && $hiring_item_list_id !== 0)
									{
										$query = "UPDATE `hiring_list` SET `asset_id`='$hiring_asset_id', `site_id`='$hiring_site_id', 
										`date`='$hiring_date', `rate`='$hiring_rate', `amount`='$hiring_amt', `remarks`='$hiring_remark', `qty`='$hiring_hour', 
										`status`='updated',`start`='$hiring_start',`end`='$hiring_end',`entry_type`='$hiring_time_entry_type' WHERE `hiring_list_id`='$hiring_item_list_id'";
									}
									else
									{
										$query = "INSERT INTO `hiring_list`
										(`company_id`, `hiring_id`, `asset_id`, `site_id`, `date`, `rate`, `amount`, `remarks`, `qty`, `status`, `start`, `end`, `entry_type`) VALUES 
										('$company_id','$hiring_id','$hiring_asset_id','$hiring_site_id','$hiring_date','$hiring_rate','$hiring_amt','$hiring_remark','$hiring_hour','updated','$hiring_start','$hiring_end','$hiring_time_entry_type')";
									};
									$query_run = mysqli_query($con, $query);
								}; 
							};

							$query = "DELETE FROM `hiring_list` WHERE `status`='' AND `hiring_id`='$hiring_id'";
							mysqli_query($con,$query);
							
							$_SESSION['hiring_id'] = $_POST['hiring_id'];
							echo "Hiring Items Updated";  
						}  
						else  
						{  
							echo "Hiring Items NOT Updated";  
						};
					};
				};
			};
		}

