	    function update_mtce()
		{
			global $con;
			$mtce_sheet_id = $_POST['mtce_sheet_id'];
			$branch_id = $_POST['mtce_sheet_branch_id'];
			$mtce_debit = $_POST['mtce_debit'];
			$mtce_amount = $_POST['mtce_amount'];
			$mtce_credit_cash = $_POST['mtce_credit_cash'];
			$mtce_amount_cash = $_POST['mtce_amount_cash'];
			$mtce_credit_stock = $_POST['mtce_credit_stock'];
			$mtce_amount_stock = $_POST['mtce_amount_stock'];
			$mtce_date = $_POST['mtce_date'];
			$serviced_by = $_POST['serviced_by'];
			$mtce_address = $_POST['mtce_address'];
			$mtce_phone = $_POST['mtce_phone'];
			$mtce_narration = $_POST['mtce_narration'];
			$company_id = $_SESSION['company_id'];
			$userdetail = $_SESSION['full_name'].':-'.time();

			if($company_id > 0)
			{
				$query = "UPDATE `mtce_sheet` SET
				`ledger_debit`='$mtce_debit', `ledger_cash`='$mtce_credit_cash', `ledger_stock`='$mtce_credit_stock', 
				`date`='$mtce_date', `amount_cash`='$mtce_amount_cash', `amount_stock`='$mtce_amount_stock', 
				`serviced_by`='$serviced_by', `address`='$mtce_address', `telephone`='$mtce_phone', 
				`narration`='$mtce_narration', `amount`='$mtce_amount',`branch_id`='$branch_id' WHERE 
				`mtce_sheet_id`='$mtce_sheet_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					//POST TRANSACTION
					
					if(isset($mtce_sheet_id) && $mtce_sheet_id > 0)
					{
						$query = "DELETE FROM `transactions` WHERE mtce_sheet_id = '$mtce_sheet_id'";
						mysqli_query($con,$query);

						//POST SERVICE COST
						if ($mtce_amount_cash !='') 
						{
							$query_dr = "INSERT INTO `transactions`(
							`company_id`,`mtce_sheet_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
							'$company_id','$mtce_sheet_id','$mtce_debit','$mtce_credit_cash','$mtce_date','$mtce_amount_cash','$mtce_amount_cash','$mtce_narration')";
							mysqli_query($con, $query_dr);

							$query_cr = "INSERT INTO `transactions`(
							`company_id`,`mtce_sheet_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
							'$company_id','$mtce_sheet_id','$mtce_credit_cash','$mtce_debit','$mtce_date','$mtce_amount_cash','$mtce_amount_cash','$mtce_narration')";
							mysqli_query($con, $query_cr);

							$query = "UPDATE `mtce_led_list` SET `status`='' WHERE `mtce_sheet_id`='$mtce_sheet_id'";
							mysqli_query($con,$query);

							$number_as = count($_POST["mtce_service_asset_id"]);
							if($number_as > 0)
							{  
								for($i=0; $i<$number_as; $i++)  
								{  
									if(trim($_POST["mtce_service_asset_id"][$i] != '') && trim($_POST["mtce_service_asset_id"][$i] != 0))  
									{  
										$mtce_service_item_list_id = $_POST['mtce_service_item_list_id'][$i];
										$mtce_service_asset_id = $_POST['mtce_service_asset_id'][$i];
										$mtce_service_site_id = $_POST['mtce_service_site_id'][$i];
										$mtce_service_remark = $_POST['mtce_service_remark'][$i];
										$mtce_service_amt = $_POST['mtce_service_amt'][$i];

										if ($mtce_service_item_list_id != '' && $mtce_service_item_list_id > 0) 
										{
											$query = "UPDATE `mtce_led_list` SET `mtce_sheet_id`='$mtce_sheet_id', 
											`asset_id`='$mtce_service_asset_id', `site_id`='$mtce_service_site_id', 
											`date`='$mtce_date', `amount`='$mtce_service_amt', `narration`='$mtce_service_remark', 
											`status`='Updated' WHERE `mtce_led_list_id`='$mtce_service_item_list_id'";
										}
										else
										{
											$query = "INSERT INTO `mtce_led_list`(`company_id`, `mtce_sheet_id`, `asset_id`, `site_id`, 
											`date`, `amount`, `narration`, `status`) 
											VALUES ('$company_id','$mtce_sheet_id','$mtce_service_asset_id','$mtce_service_site_id',
											'$mtce_date','$mtce_service_amt','$mtce_service_remark','Updated')";
										};
										mysqli_query($con, $query);
									}; 
								};
									$query = "DELETE FROM `mtce_led_list` WHERE `status`='' AND `mtce_sheet_id`='$mtce_sheet_id'";
									mysqli_query($con,$query);
							};
						};

						//POST STOCK COST
						if ($mtce_amount_stock !='') 
						{
							$query_dr = "INSERT INTO `transactions`(
							`company_id`,`mtce_sheet_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
							'$company_id','$mtce_sheet_id','$mtce_debit','$mtce_credit_stock','$mtce_date','$mtce_amount_stock','$mtce_amount_stock','$mtce_narration')";
							mysqli_query($con, $query_dr);

							$query_cr = "INSERT INTO `transactions`(
							`company_id`,`mtce_sheet_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
							'$company_id','$mtce_sheet_id','$mtce_credit_stock','$mtce_debit','$mtce_date','$mtce_amount_stock','$mtce_amount_stock','$mtce_narration')";
							mysqli_query($con, $query_cr);

							$query = "UPDATE `mtce_stock_list` SET `status`='' WHERE `mtce_sheet_id`='$mtce_sheet_id'";
							mysqli_query($con,$query);

							$number_as = count($_POST["mtce_stock_id"]);  
							if($number_as > 0)  
							{  
							for($i=0; $i<$number_as; $i++)  
							{  
								if(trim($_POST["mtce_stock_id"][$i] !== '') && trim($_POST["mtce_stock_id"][$i] !== 0))  
								{  
										$mtce_stock_id = $_POST['mtce_stock_id'][$i];
										$mtce_stock_item_list_id = $_POST['mtce_stock_item_list_id'][$i];
										$mtce_stock_asset_id = $_POST['mtce_stock_asset_id'][$i];
										$mtce_stock_site_id = $_POST['mtce_stock_site_id'][$i];
										$mtce_stock_wh_id = $_POST['mtce_stock_wh_id'][$i];
										$mtce_stock_qty = $_POST['mtce_stock_qty'][$i];
										$mtce_stock_price = $_POST['mtce_stock_price'][$i];
