		function save_sales()
		{
			global $con;
			$sales_id = $_POST['sales_id'];
			$branch_id = $_SESSION['branch_id'];
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			$user_super_id = $_POST['sales_user_super_id'];
