			$sales_credit = $_POST['sales_credit'];
			$sales_date = $_POST['sales_date'];
			$sales_supplied_by = $_POST['sales_supplied_by'];
			$sales_phone_no = $_POST['sales_phone_no'];
			$sales_location = $_POST['sales_location'];
			$sales_product = $_POST['sales_product'];
			$sales_gram = $_POST['sales_gram'];
			$sales_water = $_POST['sales_water'];
			$sales_price = $_POST['sales_price'];
			$sales_amount = $_POST['sales_amount'];
			$sales_pounds = $_POST['sales_pounds'];
			$sales_density = $_POST['sales_density'];
			$sales_karat = $_POST['sales_karat'];
			$sales_purity = $_POST['sales_purity'];
			$sales_ppp = $_POST['sales_ppp'];
			$sales_pieces = $_POST['sales_pieces'];
			$sales_narration = $_POST['sales_narration'];
			
			$method = $_POST['sales_method'];
			$purity_discount = $_POST['sales_purity_discount'];
			$discounted_karat = $_POST['sales_discounted_karat'];
			$discounted_purity = $_POST['sales_discounted_purity'];
			$discounted_ppp = $_POST['sales_discounted_ppp'];
			$discounted_amount = $_POST['sales_discounted_amount'];

			$query_last_sno = "SELECT `sno` FROM `sales` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
		    $result_last_sno = mysqli_query($con,$query_last_sno);
		    $row_last_sno = mysqli_fetch_assoc($result_last_sno);
		    $last_sno = $row_last_sno['sno'];
		    $next_sno = $last_sno + 1;

			$query = "INSERT INTO `sales`(
				`sno`,`company_id`, `user_id`, `user_super_id`, `supplier`, `phone_no`, `location`, 
				`price_per_pound`, `ledger_credit`, `ledger_debit`, 
				`date`, `product_id`, `weight`, `water`, `density`, `pounds`, `karat`, `purity`, `price`, 
				`amount`, `narration`, `number`, `branch_id`,`method`,`purity_discount`,`discounted_purity`,
				`discounted_karat`, `discounted_ppp`, `discounted_amount`) VALUES (
				'$next_sno','$company_id','$user_id','$user_super_id','$sales_supplied_by','$sales_phone_no','$sales_location','$sales_ppp','$sales_credit','$sales_debit',
				'$sales_date','$sales_product','$sales_gram','$sales_water','$sales_density','$sales_pounds','$sales_karat','$sales_purity','$sales_price',
				'$sales_amount','$sales_narration','$sales_pieces','$branch_id','$method','$purity_discount','$discounted_purity',
				'$discounted_karat','$discounted_ppp','$discounted_amount')";
		    	$query_run = mysqli_query($con, $query);

		    	if ($query_run) {

		    		//POST TRANSACTION
			    		$query = "SELECT * FROM sales WHERE `company_id`='$company_id' ORDER BY sales_id DESC";
						$result = mysqli_query($con,$query);
						$row = mysqli_fetch_assoc($result);
						$sales_id = $row['sales_id'];

			    		$query_dr = "INSERT INTO `transactions`(
		                `sales_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, `amount_debit`, 
		                `amount_credit`, `narration`) VALUES (
		                '$sales_id','$sales_debit','$sales_credit','$company_id','$user_id','$user_super_id','$sales_date','$sales_amount','$sales_amount',
		                0,'$sales_narration')";
		                mysqli_query($con, $query_dr);

		                $query_cr = "INSERT INTO `transactions`(
		                `sales_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, `amount_debit`, 
		                `amount_credit`, `narration`) VALUES (
		                '$sales_id','$sales_credit','$sales_debit','$company_id','$user_id','$user_super_id','$sales_date','$sales_amount',
		                0,'$sales_amount','$sales_narration')";
		                mysqli_query($con, $query_cr);

						$_SESSION['sales_display_company_id'] = $company_id;
						$_SESSION['sales_display_user_id'] = $user_id;
						$_SESSION['sales_display_user_super_id'] = $user_super_id;
						$_SESSION['sales_display_sales_id'] = $sales_id;

						
						if($company_id == 328 || $company_id == 329)
						{
							nexusora('sales', $sales_debit, $sales_date, $sales_amount, $sales_narration, $sales_id, $sales_id, $sales_debit, $sales_credit, $branch_id, $company_id);
						};

		            //SOLD_ITEMS
		                $number_as = count($_POST["purchase_id"]);  
						if($number_as > 0)  
						{  
						  	for($i=0; $i<$number_as; $i++)  
						  	{  
						       	if(trim($_POST["purchase_id"][$i] != ''))
						       	{  
						            $purchase_id = trim($_POST['purchase_id'][$i]);
						            $grams = $_POST['grams'][$i];
						            $water = $_POST['water'][$i];
						            $karat = $_POST['karat'][$i];
						            $amount = $_POST['amount'][$i];
						            $date = $_POST['date'][$i];
						            $supplier = $_POST['supplier'][$i];

						            $query = "INSERT INTO `sold_items`(
					                `user_super_id`,`sales_id`, `purchase_id`, `company_id`, `user_id`, `grams`, `water`, `amount`, `date`, `supplier`, `karat`) VALUES (
					                '$user_super_id','$sales_id','$purchase_id','$company_id','$user_id','$grams','$water','$amount','$date','$supplier','$karat')";
									$query_run = mysqli_query($con, $query);
						       	}
						  	} 
						};
		    	}
		}

