					$row['ledger_debit'],$row['supplier'],$row['date'],$row['time'],$row['product_id'],$row['weight'],
					$row['water'],$row['density'],$row['pounds'],$row['karat'],$row['purity'],$row['price'],
					$row['amount'],$row['narration'],$row['number'],$row['phone_no'],$row['location'],$row['price_per_pound'],
					$sold_item_top,$sold_item_down,$row['branch_id'],$sold_item_amount,$sold_item_profit,$value,
					$row['method'],$row['purity_discount'],$row['discounted_purity'],$row['discounted_karat'],$row['discounted_ppp'],$row['discounted_amount']
				);
			}
			 echo json_encode($sales_details);
		}

