		function update_sales()
		{
			global $con;
			$sales_id = $_POST['sales_id'];
			$branch_id = $_SESSION['branch_id'];
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			$user_super_id = $_POST['sales_user_super_id'];
			$sales_debit = $_POST['sales_debit'];
			$sales_credit = $_POST['sales_credit'];
			$sales_date = $_POST['sales_date'];
			$sales_supplied_by = $_POST['sales_supplied_by'];
			$sales_phone_no = $_POST['sales_phone_no'];
			$sales_location = $_POST['sales_location'];
			$sales_product = $_POST['sales_product'];
			$sales_gram = $_POST['sales_gram'];
			$sales_water = $_POST['sales_water'];
			$sales_price = $_POST['sales_price'];
			$sales_amount = $_POST['sales_amount'];
			$sales_pounds = $_POST['sales_pounds'];
			$sales_density = $_POST['sales_density'];
			$sales_karat = $_POST['sales_karat'];
			$sales_purity = $_POST['sales_purity'];
			$sales_ppp = $_POST['sales_ppp'];
			$sales_pieces = $_POST['sales_pieces'];
			$sales_narration = $_POST['sales_narration'];
