			$method = $_POST['sales_method'];
			$purity_discount = $_POST['sales_purity_discount'];
			$discounted_karat = $_POST['sales_discounted_karat'];
			$discounted_purity = $_POST['sales_discounted_purity'];
			$discounted_ppp = $_POST['sales_discounted_ppp'];
			$discounted_amount = $_POST['sales_discounted_amount'];

			$query = "UPDATE `sales` SET
				`company_id`='$company_id', `user_id`='$user_id', `user_super_id`='$user_super_id', `supplier`='$sales_supplied_by', `phone_no`='$sales_phone_no', 
				`location`='$sales_location', `price_per_pound`='$sales_ppp', `ledger_credit`='$sales_credit', `ledger_debit`='$sales_debit', `date`='$sales_date', 
				`product_id`='$sales_product', `weight`='$sales_gram', `water`='$sales_water', `density`='$sales_density', `pounds`='$sales_pounds', 
				`karat`='$sales_karat',`branch_id`='$branch_id', `purity`='$sales_purity', `price`='$sales_price', `amount`='$sales_amount', `narration`='$sales_narration', 
				`number`='$sales_pieces', `method`='$method', `purity_discount`='$purity_discount', `discounted_karat`='$discounted_karat',`discounted_purity`='$discounted_purity', 
				`discounted_ppp`='$discounted_ppp', `discounted_amount`='$discounted_amount' WHERE `sales_id`='$sales_id'";
		    	$query_run = mysqli_query($con, $query);

		    	if ($query_run) 
				{
		    		//POST TRANSACTION
					if(isset($sales_id) && $sales_id > 0)
					{
			    		$query = "DELETE FROM `transactions` WHERE `sales_id`='$sales_id'";
						mysqli_query($con,$query);

			    		$query_dr = "INSERT INTO `transactions`(
		                `sales_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, `amount_debit`, 
		                `amount_credit`, `narration`) VALUES (
		                '$sales_id','$sales_debit','$sales_credit','$company_id','$user_id','$user_super_id','$sales_date','$sales_amount','$sales_amount',
		                0,'$sales_narration')";
		                mysqli_query($con, $query_dr);

		                $query_cr = "INSERT INTO `transactions`(
		                `sales_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `user_super_id`, `date`, `amount`, `amount_debit`, 
		                `amount_credit`, `narration`) VALUES (
		                '$sales_id','$sales_credit','$sales_debit','$company_id','$user_id','$user_super_id','$sales_date','$sales_amount',
		                0,'$sales_amount','$sales_narration')";
		                mysqli_query($con, $query_cr);

						$_SESSION['sales_display_company_id'] = $company_id;
						$_SESSION['sales_display_user_id'] = $user_id;
						$_SESSION['sales_display_user_super_id'] = $user_super_id;
						$_SESSION['sales_display_sales_id'] = $sales_id;

		            //SOLD_ITEMS
		                $query = "DELETE FROM `sold_items` WHERE `sales_id`='$sales_id'";
						mysqli_query($con,$query);

		                $number_as = count($_POST["purchase_id"]);  
						if($number_as > 0)  
						{  
						  	for($i=0; $i<$number_as; $i++)  
						  	{  
						       	if(trim($_POST["purchase_id"][$i] != ''))
						       	{  
						            $purchase_id = trim($_POST['purchase_id'][$i]);
						            $grams = $_POST['grams'][$i];
						            $water = $_POST['water'][$i];
						            $karat = $_POST['karat'][$i];
						            $amount = $_POST['amount'][$i];
						            $date = $_POST['date'][$i];
						            $supplier = $_POST['supplier'][$i];

						            $query = "INSERT INTO `sold_items`(
					                `user_super_id`,`sales_id`, `purchase_id`, `company_id`, `user_id`, `grams`, `water`, `amount`, `date`, `supplier`, `karat`) VALUES (
					                '$user_super_id','$sales_id','$purchase_id','$company_id','$user_id','$grams','$water','$amount','$date','$supplier','$karat')";
									$query_run = mysqli_query($con, $query);
						       	}
						  	} 
						};
					};
		    	};
		}

