		function update_bulk_sales()
		{
			global $con;
			$bulk_sales_id = $_POST['bulk_sales_id'];
			$userdetail = $_SESSION['full_name'].':-'.time();
			
			$_SESSION['bulk_sales_id'] = $bulk_sales_id;

			$branch_id = $_SESSION['branch_id'];
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			$bulk_sales_debit = $_POST['bulk_sales_debit'];
			$bulk_sales_credit = $_POST['bulk_sales_credit'];
			$bulk_sales_date = $_POST['bulk_sales_date'];
			$bulk_sales_supplied_by = $_POST['bulk_sales_supplied_by'];
			$bulk_sales_phone_no = $_POST['bulk_sales_phone_no'];
			$bulk_sales_location = $_POST['bulk_sales_location'];
			$bulk_sales_narration = $_POST['bulk_sales_narration'];

			$query_bulk_sales_debit = "SELECT * FROM `ledgers` WHERE `ledger_id` = '$bulk_sales_debit'";
			$result_bulk_sales_debit = mysqli_query($con,$query_bulk_sales_debit);
	        if (mysqli_num_rows($result_bulk_sales_debit) > 0)
			{
				$row_bulk_sales_debit = mysqli_fetch_assoc($result_bulk_sales_debit);
				$supplier_name = $row_bulk_sales_debit['ledger_desc'];
			}
			else
			{
				$supplier_name = 'N/A';
			};

			$direct_payment_narration = $supplier_name.' - Direct Payment';

			$query_last_sno = "SELECT `sno` FROM `bulk_sales` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
			$result_last_sno = mysqli_query($con,$query_last_sno);
	        if (mysqli_num_rows($result_last_sno) > 0)
			{
				$row_last_sno = mysqli_fetch_assoc($result_last_sno);
				$last_sno = $row_last_sno['sno'];
				$next_sno = $last_sno + 1;
			}
			else
			{
				$next_sno = 1;
			};

			$query = "UPDATE `bulk_sales` SET `supplier`='$bulk_sales_supplied_by', 
			`phone_no`='$bulk_sales_phone_no', `location`='$bulk_sales_location', `ledger_credit`='$bulk_sales_credit', 
			`ledger_debit`='$bulk_sales_debit', `date`='$bulk_sales_date', `narration`='$bulk_sales_narration',
			`altered_by`='$user_id', `altered_datetime`=NOW() WHERE `bulk_sales_id`='$bulk_sales_id'";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				$query = "DELETE FROM sales WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query);

				$query = "UPDATE receipt SET deleted = '$userdetail' WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query);

				$query = "DELETE FROM journal WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query);

				//SALES
					$number_as = count($_POST["bulk_sales_selling_price"]);  
					if($number_as > 0)  
					{  
						for($i = 0; $i < $number_as; $i++)  
						{  
							if(trim($_POST["bulk_sales_selling_price"][$i]) != '' && trim($_POST["bulk_sales_selling_price"][$i]) > 0)
							{  
								$selling_price = trim($_POST['bulk_sales_selling_price'][$i]);
								$purchase_id = $_POST['bulk_sales_purchase_id'][$i];
								$purity = $_POST['bulk_sales_purity'][$i];
								$supplier = $_POST['bulk_sales_supplier'][$i];
								$ppp = $_POST['bulk_sales_price_per_pound'][$i];
								$pieces = $_POST['bulk_sales_pieces'][$i];
								$weight = $_POST['bulk_sales_weight'][$i];
								$water = $_POST['bulk_sales_water'][$i];
								$density = $_POST['bulk_sales_density'][$i];
								$karat = $_POST['bulk_sales_karat'][$i];
								$pounds = $_POST['bulk_sales_pounds'][$i];
								$purchase_price = $_POST['bulk_sales_price'][$i];
								$purchase_amount = $_POST['bulk_sales_amount'][$i];
								$sales_amount = $_POST['bulk_sales_sold_amount'][$i];

								$query_last_sno = "SELECT `sno` FROM `sales` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
								$result_last_sno = mysqli_query($con,$query_last_sno);
								if (mysqli_num_rows($result_last_sno) > 0)
								{
									$row_last_sno = mysqli_fetch_assoc($result_last_sno);
									$last_sno = $row_last_sno['sno'];
									$next_sno = $last_sno + 1;
								}
								else
								{
									$next_sno = 1;
								};

								$query_sales = "INSERT INTO `sales`(
								`sno`,`company_id`, `user_id`, `supplier`, `phone_no`, `location`, `price_per_pound`, `ledger_credit`, 
								`ledger_debit`, `date`, `product_id`, `weight`, `water`, `density`, `pounds`, `karat`, 
								`purity`, `price`, `amount`, `narration`, `number`, `branch_id`, `created_by`, `created_datetime`, `bulk_sales_id`) VALUES (
								'$next_sno','$company_id','$user_id','$bulk_sales_supplied_by','$bulk_sales_phone_no',
								'$bulk_sales_location','$ppp','$bulk_sales_credit','$bulk_sales_debit','$bulk_sales_date',1,
								'$weight','$water','$density','$pounds','$karat','$purity','$selling_price','$sales_amount',
								'$bulk_sales_narration','$pieces','$branch_id','$user_id',NOW(),'$bulk_sales_id')";
								$query_run_sales = mysqli_query($con, $query_sales);
								if ($query_run_sales) 
								{
									//POST TRANSACTION
									$query = "SELECT * FROM sales WHERE `company_id`='$company_id' ORDER BY sales_id DESC";
									$result = mysqli_query($con,$query);
									$row = mysqli_fetch_assoc($result);
									$sales_id = $row['sales_id'];

									$query_dr = "INSERT INTO `transactions`(
									`sales_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`,`bulk_sales_id`, `date`, 
									`amount`, `amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`) VALUES (
									'$sales_id','$bulk_sales_debit','$bulk_sales_credit','$company_id','$user_id','$bulk_sales_id',
									'$bulk_sales_date','$sales_amount','$sales_amount',0,'$bulk_sales_narration','$user_id',NOW())";
									mysqli_query($con, $query_dr);

									$query_cr = "INSERT INTO `transactions`(
									`sales_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`,`bulk_sales_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`) VALUES (
									'$sales_id','$bulk_sales_credit','$bulk_sales_debit','$company_id','$user_id','$bulk_sales_id',
									'$bulk_sales_date','$sales_amount',0,'$sales_amount','$bulk_sales_narration','$user_id',NOW())";
									mysqli_query($con, $query_cr);

									$query = "INSERT INTO `sold_items`(
									`sales_id`, `purchase_id`, `company_id`, `user_id`, `grams`, `water`, `amount`, `date`, 
									`supplier`,`bulk_sales_id`, `density`, `karat`, `pounds`) VALUES ('$sales_id','$purchase_id',
									'$company_id','$user_id','$weight','$water','$purchase_amount','$bulk_sales_date','$supplier',
									'$bulk_sales_id','$density','$karat','$pounds')";
									mysqli_query($con, $query);
								};
							}
						} 
					};

				//DIRECT PAYMENTS
				$number_as = count($_POST["bulk_sales_payment_amount"]);  
				if($number_as > 0)  
				{  
					for($i = 0; $i < $number_as; $i++)  
					{  
						if(trim($_POST["bulk_sales_payment_amount"][$i] != ''))
						{  
							$ledger_id = trim($_POST['bulk_sales_payment_ledger_id'][$i]);
							$group_id = trim($_POST['bulk_sales_payment_ledger_group_id'][$i]);
							$mode = trim($_POST['bulk_sales_payment_mode'][$i]);
							$amount = trim($_POST['bulk_sales_payment_amount'][$i]);

							if($group_id != 6)
							{
								$query_last_sno = "SELECT `sno` FROM `journal` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
								$result_last_sno = mysqli_query($con,$query_last_sno);
								if (mysqli_num_rows($result_last_sno) > 0)
								{
									$row_last_sno = mysqli_fetch_assoc($result_last_sno);
									$last_sno = $row_last_sno['sno'];
									$next_sno = $last_sno + 1;
								}
								else
								{
									$next_sno = 1;
								};

								$query_journal = "INSERT INTO `journal`(
								`sno`, `company_id`, `user_id`, `reference_no`, `narration`,  `bulk_sales_id`, `mode`, 
								`ledger_debit`, `ledger_credit`, `amount`, `date`, `branch_id`, `created_by`, `created_datetime`) VALUES (
								'$next_sno','$company_id','$user_id','$bulk_sales_id','$direct_payment_narration','$bulk_sales_id','$mode',
								'$ledger_id','$bulk_sales_debit','$amount','$bulk_sales_date','$branch_id','$user_id',NOW())";
								$query_run_journal = mysqli_query($con, $query_journal);
								
								if ($query_run_journal) 
								{
									//POST TRANSACTION
										$query = "SELECT * FROM journal WHERE `company_id`='$company_id' ORDER BY journal_id DESC";
										$result = mysqli_query($con,$query);
										$row = mysqli_fetch_assoc($result);
										$journal_id = $row['journal_id'];
										
										$query_dr = "INSERT INTO `transactions`(
										`journal_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_sales_id`) VALUES (
										'$journal_id','$ledger_id','$bulk_sales_debit','$company_id','$user_id','$bulk_sales_date',
										'$amount','$amount',0,'$direct_payment_narration','$user_id',NOW(),'$bulk_sales_id')";
										mysqli_query($con, $query_dr);

										$query_cr = "INSERT INTO `transactions`(
										`journal_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
										`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_sales_id`) VALUES (
										'$journal_id','$bulk_sales_debit','$ledger_id','$company_id','$user_id','$bulk_sales_date',
										'$amount',0,'$amount','$direct_payment_narration','$user_id',NOW(),'$bulk_sales_id')";
										mysqli_query($con, $query_cr);
								};
							}
							else
							{
								$query_last_sno = "SELECT `sno` FROM `receipt` WHERE `company_id` ='$company_id' ORDER BY `sno` DESC";
								$result_last_sno = mysqli_query($con,$query_last_sno);
								if (mysqli_num_rows($result_last_sno) > 0)
								{
									$row_last_sno = mysqli_fetch_assoc($result_last_sno);
									$last_sno = $row_last_sno['sno'];
									$next_sno = $last_sno + 1;
								}
								else
								{
									$next_sno = 1;
								};

								$query_receipt = "INSERT INTO `receipt`(`sno`,`company_id`, `user_id`, `ledger_credit`, `date`, 
								`amount`, `narration`, `reference_no`, `mode`, `received_from`, `branch_id`, `bulk_sales_id`,
								`created_by`, `created_datetime`) VALUES ('$next_sno','$company_id','$user_id',
								'$ledger_id','$bulk_sales_date','$amount','$direct_payment_narration','$bulk_sales_id','$mode',
								'$supplier_name','$branch_id','$bulk_sales_id','$user_id',NOW())";
								$query_run_receipt = mysqli_query($con, $query_receipt);

								if ($query_run_receipt) 
								{
									//POST TRANSACTION
									$query = "SELECT * FROM receipt WHERE `company_id`='$company_id' ORDER BY receipt_id DESC";
									$result = mysqli_query($con,$query);
									$row = mysqli_fetch_assoc($result);
									$receipt_id = $row['receipt_id'];

									//RECEIPT_ITEMS
									$query_dr = "INSERT INTO `transactions`(
									`receipt_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_sales_id`) VALUES (
									'$receipt_id','$ledger_id','$bulk_sales_debit','$company_id','$user_id','$bulk_sales_date',
									'$amount','$amount',0,'$direct_payment_narration','$user_id',NOW(),'$bulk_sales_id')";
									mysqli_query($con, $query_dr);

									$query_cr = "INSERT INTO `transactions`(
									`receipt_id`,`ledger_id`, `ledger_id_contra`, `company_id`, `user_id`, `date`, `amount`, 
									`amount_debit`, `amount_credit`, `narration`, `created_by`, `created_datetime`, `bulk_sales_id`) VALUES (
									'$receipt_id','$bulk_sales_debit','$ledger_id','$company_id','$user_id','$bulk_sales_date',
									'$amount',0,'$amount','$direct_payment_narration','$user_id',NOW(),'$bulk_sales_id')";
									mysqli_query($con, $query_cr);
								};
							};
						};
					};
				};
			};
		}

