		function delete_bulk_sales()
		{
			global $con;
			$userdetail = $_SESSION['full_name'].':-'.time();
			if(isset($_POST['bulk_sales_id']) && $_POST['bulk_sales_id'] > 0)
			{
				$bulk_sales_id = $_POST['bulk_sales_id'];

				$query_bulk_sales = "DELETE FROM bulk_sales WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query_bulk_sales);

				$query_sales = "DELETE FROM sales WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query_sales);

				$query_receipt = "UPDATE receipt SET deleted='$userdetail' WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query_receipt);

				$query_journal = "DELETE FROM journal WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query_journal);

				$query_trans = "DELETE FROM `transactions` WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query_trans);

				$query_sold_item = "DELETE FROM `sold_items` WHERE `bulk_sales_id`='$bulk_sales_id'";
				mysqli_query($con, $query_sold_item);
			};
		}

