			`customer`, `shelf`,`narration`, `sno`, `status`, `branch_id`,`created_by`, `created_datetime`) 
			VALUES ('$company_id','$date','$debit','$credit','$amount','$stock_amount','$overhead_amount',
			'$customer','$shelf','$narration','$sno',7,'$branch_id','$user_id',NOW())";
