		function update_job_card()
		{
			global $con;
			$job_card_id = $_POST['job_card_id'];
			$debit = $_POST['job_card_debit'];
			$credit = 6;
			$amount = $_POST['job_card_amount'];
			$stock_amount = $_POST['job_card_stock_amount'];
			$overhead_amount = $_POST['job_card_overhead_amount'];
			$customer = $_POST['job_card_customer'];
			$date = $_POST['job_card_date'];
			$shelf = $_POST['job_card_shelf_no'];
			$narration = $_POST['job_card_narration'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$userdetail = $_SESSION['full_name'].':-'.time();

			$query = "UPDATE `job_card` SET `date`='$date', `ledger_debit`='$debit', `amount`='$amount', 
			`amount_stock`='$stock_amount', `amount_overhead`='$overhead_amount', `customer`='$customer', 
			`shelf`='$shelf',`narration`='$narration',`altered_by`='$user_id', `altered_datetime`=NOW() 
			WHERE `job_card_id`='$job_card_id'";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				//POST TRANSACTION
				if(isset($job_card_id) && $job_card_id > 0)
				{
					$query_trans_del = "DELETE FROM `transactions` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `job_card_items` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `stock_adjustment` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `stock_adjustment_items` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `job_cost` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);

					$query_dr = "INSERT INTO `transactions`(
					`company_id`,`job_card_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
					'$company_id','$job_card_id','$debit','$credit','$date','$amount','$amount','$narration')";
					mysqli_query($con, $query_dr);

					$query_cr = "INSERT INTO `transactions`(
					`company_id`,`job_card_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
					'$company_id','$job_card_id','$credit','$debit','$date','$amount','$amount','$narration')";
					mysqli_query($con, $query_cr);

					$number_as = count($_POST["job_card_service"]);  
					if($number_as > 0)  
					{  
						for($i=0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["job_card_service"][$i]) != '' && trim($_POST["job_card_service"][$i]) != 0)  
							{  
								$job_card_service = $_POST['job_card_service'][$i];
								$job_card_service_qty = $_POST['job_card_service_qty'][$i];
								$job_card_service_price = $_POST['job_card_service_price'][$i];
								$job_card_service_amt = $_POST['job_card_service_amt'][$i];
								$query = "INSERT INTO `job_card_items`
								(`company_id`, `job_card_id`, `service_id`,`date`, `price`, `amount`, `qty`, `created_by`, 
								`created_datetime`) VALUES ('$company_id','$job_card_id','$job_card_service','$date',
								'$job_card_service_price','$job_card_service_amt','$job_card_service_qty','$user_id', NOW())";
								mysqli_query($con, $query);
							};
						};
					};

					$number_st = count($_POST["job_card_desc"]);  
					if($number_st > 0)  
					{  
						$stk_adj_adjusted_by = $_SESSION['full_name'];
						$stk_adj_ref_no = 'Stock Used';
						$stk_adj_narration = 'Items used for Cleaning/Washing';
						
						$query = "INSERT INTO `stock_adjustment`(`company_id`, `reference_no`, `date`, `narration`, 
						`adjusted_by`, `job_card_id`, `created_by`, `created_datetime`) 
						VALUES ('$company_id','$stk_adj_ref_no','$date','$stk_adj_narration','$stk_adj_adjusted_by',
						'$job_card_id','$user_id',NOW())";
						$query_run_st = mysqli_query($con, $query);
		
						if ($query_run_st) 
						{
							$query = "SELECT * FROM stock_adjustment ORDER BY stock_adj_id DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);
							$stock_adj_id  = $row['stock_adj_id'];
		 
							for($i=0; $i<$number_st; $i++)  
							{  
								if(trim($_POST["job_card_desc"][$i]) != '' && trim($_POST["job_card_desc"][$i]) != 0)  
								{  
									$stk_adj_item_id = $_POST['job_card_desc'][$i];
									$job_card_price = $_POST['job_card_price'][$i];
									$job_card_amt = $_POST['job_card_amt'][$i];
									$stock_adj_wh = $_POST['job_card_loc_id'][$i];
									$job_card_qty = $_POST['job_card_qty'][$i];
									$query_stk_adj_items = "INSERT INTO `stock_adjustment_items`
									(`company_id`,`stock_adj_id`, `date`, `stock_item_id`, `job_card_id`, `warehouse_id`, `price`, 
									`amount`,`qty_out`) VALUES ('$company_id','$stock_adj_id','$date','$stk_adj_item_id',
									'$job_card_id','$stock_adj_wh','$job_card_price','$job_card_amt','$job_card_qty')";
									mysqli_query($con, $query_stk_adj_items);
								};
							};
						}
					};

					$number_oh = count($_POST["job_card_overhead"]);  
					if($number_oh > 0)  
					{  
						for($i=0; $i<$number_oh; $i++)  
						{  
							if(trim($_POST["job_card_overhead"][$i] !== '') && trim($_POST["job_card_overhead"][$i] !== 0))  
							{  
								$job_card_overhead = $_POST['job_card_overhead'][$i];
								$job_card_overhead_amt = $_POST['job_card_overhead_amt'][$i];
								$job_card_overhead_remarks = $_POST['job_card_overhead_remarks'][$i];
								$query_oh = "INSERT INTO `job_cost`
								(`company_id`, `job_card_id`, `description`,`date`, `amount`, `remarks`, `created_by`, 
								`created_datetime`) VALUES ('$company_id','$job_card_id','$job_card_overhead','$date',
								'$job_card_overhead_amt','$job_card_overhead_remarks','$user_id', NOW())";
								mysqli_query($con, $query_oh);
							};
						};
					};
				};
			};
		}

