			if(isset($_POST['job_card_id']) && $_POST['job_card_id'] > 0)
			{
				$job_card_id = $_POST['job_card_id'];
				$query = "DELETE FROM `job_card`WHERE `job_card_id`='$job_card_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					$query_trans_del = "DELETE FROM `transactions` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);

					$query_sold_item_del = "DELETE FROM `job_card_items` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_sold_item_del);

					$query_sold_item_del = "DELETE FROM `job_cost` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_sold_item_del);

					$query_sold_item_del = "DELETE FROM `stock_adjustment` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_sold_item_del);

					$query_sold_item_del = "DELETE FROM `stock_adjustment_items` WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_sold_item_del);

					$query_trans_del = "UPDATE `receipt` SET deleted='userfetail' WHERE `job_card_id`='$job_card_id'";
					mysqli_query($con, $query_trans_del);
					
					echo "deleted";  
