	//NON-DEDUCTIBLE_SALES
		function nds_sales_unique()
		{
			global $con;
			
			$data = array();
			$user_type_id = $_SESSION['user_type_id'];
			$cash_ledger_id = $_SESSION['cash_ledger_id'];
			$company_id = stripslashes($_SESSION['company_id']);
			$company_id = mysqli_real_escape_string($con,$company_id);
			$branch_id = stripslashes($_SESSION['branch_id']);
			$branch_id = mysqli_real_escape_string($con,$branch_id);

			$sql = "SELECT nds_sales_id FROM nds_sales WHERE company_id = ? ORDER BY nds_sales_id DESC";
			$stmt = $con->prepare($sql); 
			$stmt->bind_param("i", $company_id);
			$stmt->execute();
			$stmt_result = $stmt->get_result();

			if($stmt_result->num_rows > 0)
			{
				$row = $stmt_result->fetch_assoc();
				$nds_sales_id = $row['nds_sales_id']+1;
				/*$query = "SELECT nds_sales_id FROM nds_sales WHERE company_id = '$company_id' ORDER BY nds_sales_id DESC";
				$result = mysqli_query($con,$query);
				$row = mysqli_fetch_assoc($result);*/
			}
			else
			{
				$nds_sales_id = 0;
			};
			$unique_no = $branch_id.''.$nds_sales_id;
			
			array_push($data, 
				$unique_no, $user_type_id, $cash_ledger_id
			);
			echo json_encode($data);
			//echo $unique_no;
		}

