		function nds_sales_item_price()
		{
			global $con;
			/*$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$stock_item_id = $_POST['stock_item_id'];*/
			$stock_item_id = stripslashes($_POST['stock_item_id']);
			$stock_item_id = mysqli_real_escape_string($con,$stock_item_id);
			$company_id = stripslashes($_SESSION['company_id']);
			$company_id = mysqli_real_escape_string($con,$company_id);
			$branch_id = stripslashes($_SESSION['branch_id']);
			$branch_id = mysqli_real_escape_string($con,$branch_id);
			$data = array();
			$sql = "SELECT * FROM price_list WHERE stock_item_id=? AND 
			company_id=? AND branch_id=? ORDER BY date DESC";
			$stmt = $con->prepare($sql); 
			$stmt->bind_param("iii", $stock_item_id, $company_id, $branch_id);
			$stmt->execute();
			$stmt_result = $stmt->get_result();

			if($stmt_result->num_rows > 0)
			{
				$row_pl = $stmt_result->fetch_assoc();
				
			/*$query_pl = "SELECT * FROM price_list WHERE stock_item_id='$stock_item_id' AND 
			company_id='$company_id' AND branch_id='$branch_id' ORDER BY date DESC";
			$result_pl = mysqli_query($con,$query_pl);
			$row_pl = mysqli_fetch_assoc($result_pl);*/
			$pl_price = $row_pl['price'];
			}
			else {
				$pl_price = 0;
			}

			$sql = "SELECT * FROM stock_items WHERE stock_item_id=?";
			$stmt = $con->prepare($sql); 
			$stmt->bind_param("i", $stock_item_id);
			$stmt->execute();
			$stmt_result = $stmt->get_result();

			if($stmt_result->num_rows > 0)
			{
				$row = $stmt_result->fetch_assoc();
				
				/*$query = "SELECT * FROM stock_items WHERE stock_item_id='$stock_item_id'";
				$result = mysqli_query($con,$query);
				$row = mysqli_fetch_assoc($result);*/
				$price = $row['price_cash'];
				$block_negative = $row['block_negative'];
			}
			else
			{
				$price = 0;
				$block_negative = 'No';
			};

			if($pl_price > 0)
			{
				$selling_price = $pl_price;
			}
			else
			{
				$selling_price = $price;
			};
			array_push($data, 
				$selling_price,
				$block_negative
			);
			echo json_encode($data);
		}

