	//WAYBILL
		function waybill_unique()
		{
			global $con;
			
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$query = "SELECT waybill_id FROM waybill WHERE company_id = '$company_id' ORDER BY waybill_id DESC";
			$result = mysqli_query($con,$query);
			$row = mysqli_fetch_assoc($result);

			$unique_no = $branch_id.''.$row['waybill_id']+1;

			echo $unique_no;
		}

		function waybill_new_modal_list()
		{
			global $con;
			$nds_sales_id = $_POST['nds_sales_id'];
			$company_id = $_SESSION['company_id'];
			$i = 0;
			$value = '<table table class="table table-hover table-bordered table-sm" width="100%" cellspacing="0" style="font-size: 14px" id="waybill_items_table">
				<thead>
					<tr>
						<th width="40%">Description</th>
						<th width="25%" class="action-td">Warehouse</th>
						<th width="15%" class="action-td">Qty</th>
						<th width="15%" class="action-td">Qty Issue</th>
						<th width="5%" class="action-td">Action</th>
					</tr>
				</thead>
				<tbody>';
					$sql = "SELECT * FROM customer_warehouse WHERE nds_sales_id = '$nds_sales_id'";
					$sql_run = mysqli_query($con, $sql);
					if(!empty($sql_run) && mysqli_num_rows($sql_run) > 0)
					{
						while($row = mysqli_fetch_assoc($sql_run))
						{
							$i++;
							$stock_item_id = $row['stock_item_id'];
							$qty_purchased = $row['qty_in'];
							$warehouse_id = $row['warehouse_id'];

							$sql_sl="SELECT SUM(qty) AS qty FROM stock_sales_items WHERE nds_sales_id = '$nds_sales_id' AND stock_item_id = '$stock_item_id '";
							$sql_run_sl = mysqli_query($con, $sql_sl);
							if(!empty($sql_run_sl) && mysqli_num_rows($sql_run_sl) > 0)
							{
								$row_sl = mysqli_fetch_assoc($sql_run_sl);
								$qty_supplied = $row_sl['qty'];
							}
							else
							{
								$qty_supplied = 0;
							};

							$qty_pending = $qty_purchased - $qty_supplied;

