		function waybill_send_code()
		{
			global $con;
			$telephone = $_POST['telephone'];
			$company_id = $_SESSION['company_id'];
			$name = $_POST['name'];
			
			$sql = "SELECT trading_name FROM company WHERE company_id = '$company_id'";
			$sql_run = mysqli_query($con, $sql);
			if(!empty($sql_run) && mysqli_num_rows($sql_run) > 0)
			{
				$row = mysqli_fetch_assoc($sql_run);
				$company_name = strtoupper($row['trading_name']);
			}
			else
			{
				$company_name = 'NO COMPANY';
			};
			
			$phone = substr($telephone, 1, 9);

			$code = random_int(1000, 9999);
			$to = '233'.$phone;
			$message = 'Dear '.$name.', your secret code from '.$company_name.' is '.$code.'. Present it for your waybill. Thanks';
			sendSMS($to, $message);
			echo $code;
		}

