		function save_waybill()
		{
			global $con;
			$waybill_id = $_POST['waybill_id'];
			if(isset($_POST['waybill_nds_sales_id']) && $_POST['waybill_nds_sales_id'] > 0)
			{
				$nds_sales_id = $_POST['waybill_nds_sales_id'];
			}
			else
			{
				$nds_sales_id = 0;
			};
			$customer_id = $_POST['waybill_customer_id'];
			$date = $_POST['waybill_date'];
			$driver = $_POST['waybill_driver'];
			$car_number = $_POST['waybill_car_number'];
			$destination = $_POST['waybill_destination'];
			$issued_by = $_POST['waybill_issued_by'];
			$approved_by = $_POST['waybill_approved_by'];
			$narration = $_POST['waybill_narration'];
			$driver_telephone = $_POST['waybill_driver_telephone'];
			$company_id = $_SESSION['company_id'];
			//if(isset($_POST['waybill_branch_id']) && $_POST['waybill_branch_id'] > 0)
			//{
				$branch_id = $_POST['waybill_branch_id'];
			/*}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};*/
			$user_id = $_SESSION['user_id'];


			$unique = $_POST['waybill_unique'];
			$query_uniq = "SELECT * FROM waybill WHERE waybill_unique = '$unique'";
			$result_uniq = mysqli_query($con,$query_uniq);
			if(!empty($result_uniq) && mysqli_num_rows($result_uniq) > 0)
			{
				echo 'exist';
			}
			else
			{
				if($company_id > 0)
				{
					$query = "SELECT sno FROM waybill WHERE company_id = '$company_id' AND branch_id = '$branch_id' ORDER BY sno DESC";
					$result = mysqli_query($con,$query);
					$row = mysqli_fetch_assoc($result);
					$sno = $row['sno'] + 1;

					$query = "INSERT INTO `waybill`(
					`company_id`, `date`, `nds_sales_id`, `drivers_name`, `car_number`, `customer_id`, `telephone`, 
					`destination`, `narration`, `sno`, `branch_id`, `prepared_by`, `approved_by`, `created_by`, 
					`created_datetime`, `waybill_unique`) VALUES ('$company_id','$date','$nds_sales_id','$driver','$car_number', 
					'$customer_id','$driver_telephone','$destination','$narration','$sno','$branch_id',
					'$issued_by','$approved_by','$user_id', NOW(),'$unique')";
					$query_run = mysqli_query($con, $query);

					if ($query_run)
					{
						//POST TRANSACTION
							$query = "SELECT * FROM waybill ORDER BY waybill_id DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);
							$waybill_id = $row['waybill_id'];
							
							$_SESSION['waybill_id'] = $row['waybill_id'];

							$number_as = count($_POST["waybill_stock_item_id"]);  
							if($number_as > 0)  
							{  
								for($i = 0; $i<$number_as; $i++)  
								{  
									if(trim($_POST["waybill_stock_item_id"][$i]) != '' && trim($_POST["waybill_stock_item_id"][$i]) != 0)  
									{  
										$stock_item_id = $_POST['waybill_stock_item_id'][$i];
										$warehouse_id = $_POST['waybill_warehouse_id'][$i];
										//$qty = $_POST['waybill_qty'][$i];
										$qty = $_POST['waybill_qty_issue'][$i];
										if($qty > 0)
										{
