											$query = "INSERT INTO `customer_warehouse`
											(`company_id`,`branch_id`,`customer_id`, `waybill_id`, `stock_item_id`, `warehouse_id`, `date`, 
											`qty_out`) VALUES ('$company_id','$branch_id','$customer_id','$waybill_id','$stock_item_id',
