		function save_swap()
		{
			global $con;
			$swap_id = $_POST['swap_id'];
			$customer_id = $_POST['swap_customer_id'];
			$prepared_by = $_POST['swap_prepared_by'];
			$date = $_POST['swap_date'];
			$approved_by = $_POST['swap_approved_by'];
			$narration = $_POST['swap_narration'];
			$company_id = $_SESSION['company_id'];
			if(isset($_POST['swap_branch_id']) && $_POST['swap_branch_id'] > 0)
			{
				$branch_id = $_POST['swap_branch_id'];
			}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};
			$user_id = $_SESSION['user_id'];
			$warehouse_id = $_SESSION['warehouse_id'];


			$unique = $_POST['swap_unique'];
			$query_uniq = "SELECT * FROM swap WHERE swap_unique = '$unique'";
			$result_uniq = mysqli_query($con,$query_uniq);
			if(!empty($result_uniq) && mysqli_num_rows($result_uniq) > 0)
			{
				echo 'exist';
			}
			else
			{
				if($company_id > 0)
				{
					$query = "SELECT sno FROM swap WHERE company_id = '$company_id' AND branch_id = '$branch_id' ORDER BY sno DESC";
					$result = mysqli_query($con,$query);
					$row = mysqli_fetch_assoc($result);
					$sno = $row['sno'] + 1;

					$query = "INSERT INTO `swap`(
					`company_id`, `branch_id`, `date`, `customer_id`, `prepared_by`, `approved_by`, `narration`, 
					`sno`, `created_by`, `created_datetime`, `swap_unique`) VALUES ('$company_id','$branch_id','$date', '$customer_id',
					'$prepared_by','$approved_by','$narration','$sno','$user_id', NOW(),'$unique')";
					$query_run = mysqli_query($con, $query);

					if ($query_run)
					{
						//POST TRANSACTION
							$query = "SELECT * FROM swap ORDER BY swap_id DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);

							$swap_id = $row['swap_id'];
							$_SESSION['swap_id'] = $row['swap_id'];

							$number_as = count($_POST["swap_consumption_qty_swap"]);  
							if($number_as > 0)  
							{  
								for($i=0; $i<$number_as; $i++)  
								{  
									if(trim($_POST["swap_consumption_qty_swap"][$i]) != '' && trim($_POST["swap_consumption_qty_swap"][$i]) != 0)  
									{  
										$stock_item_id = $_POST['swap_consumption_item_id'][$i];
										$qty = $_POST['swap_consumption_qty_swap'][$i];
										$query = "INSERT INTO `customer_warehouse`
										(`company_id`,`branch_id`,`customer_id`, `swap_id`, `stock_item_id`, `warehouse_id`, `date`, 
										`qty_out`) VALUES ('$company_id','$branch_id','$customer_id','$swap_id','$stock_item_id',
										'$warehouse_id', '$date', '$qty')";
										mysqli_query($con, $query);
									};
								}
							};

							$number_pro = count($_POST["swap_production_item_id"]);  
							if($number_pro > 0)  
							{  
								for($i=0; $i<$number_pro; $i++)  
								{  
									if(trim($_POST["swap_production_item_id"][$i]) != '' && trim($_POST["swap_production_item_id"][$i]) != 0)  
									{  
										$stock_item_id = $_POST['swap_production_item_id'][$i];
										$qty = $_POST['swap_production_qty'][$i];
										$query = "INSERT INTO `customer_warehouse`
										(`company_id`,`branch_id`,`customer_id`, `swap_id`, `stock_item_id`, `warehouse_id`, `date`, 
										`qty_in`) VALUES ('$company_id','$branch_id','$customer_id','$swap_id','$stock_item_id',
										'$warehouse_id', '$date', '$qty')";
										mysqli_query($con, $query);
									};
								}
							};
							echo 'saved';
					};
				};
			};
		}

