						<td>
							<input type="text" name="swap_qty[]" class="form-control bg-light text-center swap_qty" id="swap_qty'.$i.'" data-id="'.$i.'" style="border-width:0px">
						</td>
						<td>
							<input type="text" name="swap_price[]" class="form-control bg-light text-right swap_price" id="swap_price'.$i.'" data-id="'.$i.'" style="border-width:0px">
						</td>
						<td>
							<input type="text" name="swap_amt[]" class="form-control bg-light text-right swap_amt" id="swap_amt'.$i.'" style="border-width:0px">
						</td>
						<td>';
							if($i > 1)
							{
								$value .= '<a href="#" id="delete_swap_item" data-id="'.$i.'"><i class="fa fa-trash fa-sm"></i></a>';
							};
						$value .= '</td>
					</tr>';
				};
				$value .= '</tbody>
			</table>';

			$data = array();
			$query = "SELECT * FROM swap WHERE swap_id='$swap_id'";
			$result = mysqli_query($con,$query);
			while($row=mysqli_fetch_assoc($result))
			{
				array_push($data, 
					$row['swap_id'], $row['date'], $row['ledger_debit'], $row['ledger_credit'],
					$row['amount'], $row['telephone'],
					$row['customer_id'], $value, $row['narration'], $row['branch_id']
				);
			}
			echo json_encode($data);
		}

