		function update_swap()
		{
			global $con;
			$swap_id = $_POST['swap_id'];
			$debit = $_POST['swap_debit'];
			$credit = $_POST['swap_credit'];
			$amount = $_POST['swap_amount'];
			$customer_id = $_POST['swap_customer_select'];
			$telephone = $_POST['swap_telephone'];
			$date = $_POST['swap_date'];
			$issued_by = $_POST['swap_issued_by'];
			$narration = $_POST['swap_narration'];
			$company_id = $_SESSION['company_id'];
			if(isset($_POST['swap_branch_id']) && $_POST['swap_branch_id'] > 0)
			{
				$branch_id = $_POST['swap_branch_id'];
			}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};
			$user_id = $_SESSION['user_id'];
			$query = "UPDATE `swap` SET `date`='$date',`ledger_debit`='$debit',
			`amount`='$amount',`telephone`='$telephone', `customer_id`='$customer_id',
			`narration`='$narration', `altered_by`='$user_id', `altered_datetime`=NOW(), 
			`branch_id`='$branch_id' WHERE `swap_id`='$swap_id'";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				//POST TRANSACTION
				if(isset($swap_id) && $swap_id > 0)
				{
					$query_trans_del = "DELETE FROM `transactions` WHERE `swap_id`='$swap_id'";
					mysqli_query($con, $query_trans_del);
					$query_trans_del = "DELETE FROM `customer_warehouse` WHERE `swap_id`='$swap_id'";
					mysqli_query($con, $query_trans_del);


					$query_dr = "INSERT INTO `transactions`(
					`company_id`,`swap_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
					'$company_id','$swap_id','$debit','$credit','$date','$amount','$amount','$narration')";
					mysqli_query($con, $query_dr);

					$query_cr = "INSERT INTO `transactions`(
					`company_id`,`swap_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
					'$company_id','$swap_id','$credit','$debit','$date','$amount','$amount','$narration')";
					mysqli_query($con, $query_cr);

					$number_as = count($_POST["stock_sales_desc"]);  
					if($number_as > 0)  
					{  
						for($i=0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["stock_sales_desc"][$i]) != '' && trim($_POST["stock_sales_desc"][$i]) != 0)  
							{  
								$stock_item_id = $_POST['stock_sales_desc'][$i];
								$warehouse_id = $_POST['swap_loc'][$i];
								$qty = $_POST['swap_qty'][$i];
								$price = $_POST['swap_price'][$i];
								$amt = $_POST['swap_amt'][$i];
								$query = "INSERT INTO `customer_warehouse`
								(`company_id`,`branch_id`,`customer_id`, `swap_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, 
								`amount`, `qty_in`) VALUES ('$company_id','$branch_id','$customer_id','$swap_id','$stock_item_id',
								'$warehouse_id', '$date','$price','$amt','$qty')";
								mysqli_query($con, $query);
							}  
						}
						echo "nds Sales Items Updated";
						$_SESSION['swap_id'] = $swap_id;
					}  
					else  
					{  
						echo "nds Sales Items NOT Updated";  
					};
				};
			};
		}

		function reprint_swap()
		{
			global $con;
			$_SESSION['swap_id'] = $_POST['swap_id'];
		}

		function delete_swap()
		{
			global $con;
			if(isset($_POST['swap_id']) && $_POST['swap_id'] > 0)
			{
				$swap_id = $_POST['swap_id'];
				$query = "DELETE FROM `swap`WHERE `swap_id`='$swap_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					$query_trans_del = "DELETE FROM `customer_warehouse` WHERE `swap_id`='$swap_id'";
					mysqli_query($con, $query_trans_del);
				};
			};
		}

		function search_swap_by_name()
		{
			global $con;
			$name = $_POST['name'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$value = "";
			if ($_SESSION['user_type'] == 'Ultra_Super_User' OR $_SESSION['user_type'] == 'Super_User' OR ($_SESSION['user_type'] == 'Normal_User' AND $_SESSION['user_type_id'] == 2))
			{
				$query = "SELECT w.*, c.first_name, c.last_name, c.phone_number FROM swap w 
				JOIN customer c ON w.customer_id=c.customer_id WHERE 
				(w.company_id = '$company_id' AND c.first_name LIKE '%".$name."%') OR 
				(w.company_id = '$company_id' AND c.last_name LIKE '%".$name."%') OR 
				(w.company_id = '$company_id' AND c.phone_number LIKE '%".$name."%') 
				ORDER BY w.date ASC";
			}
			else
			{
				$query = "SELECT w.*, c.first_name, c.last_name, c.phone_number FROM swap w 
				JOIN customer c ON w.customer_id=c.customer_id WHERE 
				(w.company_id = '$company_id' AND w.branch_id = '$branch_id' AND c.first_name LIKE '%".$name."%') OR 
				(w.company_id = '$company_id' AND w.branch_id = '$branch_id' AND c.last_name LIKE '%".$name."%') OR 
				(w.company_id = '$company_id' AND w.branch_id = '$branch_id' AND c.phone_number LIKE '%".$name."%') 
				ORDER BY w.date ASC";
			};

			$query_run = mysqli_query($con, $query);

			$value = '<table class="table table-hover table-bordered table-sm" id="swapTable" width="100%" cellspacing="0">
				<thead>
					<tr>
						<th class = "action-td">Sales ID</th>
						<th class = "action-td">Date</th>
						<th>Customer</th>
						<th class = "action-td">Amount</th>
						<th class = "action-td">Reference No</th>
						<th>Debit Ledger</th>
						<th class = "action-td">Action</th>
					</tr>
				</thead>
				<tbody class="pv-table-body">';

			
				if (mysqli_num_rows($query_run) > 0)
				{
					while($row = mysqli_fetch_assoc($query_run))
					{
						$ledger_cr = $row['ledger_debit'];
						$query_ledger = "SELECT * FROM ledgers WHERE ledger_id='$ledger_cr'";
						$query_ledger_run = mysqli_query($con, $query_ledger);
						$row_ledger = mysqli_fetch_assoc($query_ledger_run);

						$amount = $row['amount'];
						$amount_f = number_format($amount, 2, '.', ',');
						
						$value .= '<tr>
							<td class = "action-td">
								<a href="#" id="btn_edit_swap" data-id="'.$row['swap_id'].'">'.$row['sno'].'</a>
							</td>
							<td class = "action-td">'.$row['date'].'</td>
							<td>'.$row['supplied_by'].'</td>
							<td class = "amt-td">'.$amount_f.'</td>
							<td class = "action-td">'.$row['reference_no'].'</td>
							<td>'.$row_ledger['ledger_desc'].'</td>
							<td class = "action-td">';
								
								if ($_SESSION['user_type'] == 'Ultra_Super_User' OR $_SESSION['user_type'] == 'Super_User' OR ($_SESSION['user_type'] == 'Normal_User' AND $_SESSION['Edit_swap'] == 'Yes')) 
								{
									$value .= '<a href="#" id="btn_edit_swap" data-id="'.$row['swap_id'].'">Edit</a>';
								};
								
									//$value .= '<a href="#" id="btn_display_swap" data-id="'.$row['swap_id'].'">Display</a>';
									$value .= ' | <a href="#" id="btn_swap_invoice_reprint" 
										data-id="'.$row['swap_id'].'"
										data-id1="'.$row['supplied_by'].'"
									>
										Reprint</a>';
								
								if ($_SESSION['user_type'] == 'Ultra_Super_User' OR $_SESSION['user_type'] == 'Super_User' OR ($_SESSION['user_type'] == 'Normal_User' AND $_SESSION['Delete_swap'] == 'Yes'))
								{
									$value .= ' | <a href="#" id="btn_delete_swap" data-id="'.$row['swap_id'].'">Delete</a>';
								};
							
							$value .= '</td>
						</tr>';
					}
				}
				else
				{
					$value .= 'No nds Sales Not Found';
				};
				$value .= '</tbody>
			</table>';
			echo $value;
		}

