		function stock_sales_item_price()
		{
			global $con;
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$stock_item_id = $_POST['stock_item_id'];
			$data = array();

			$query_spi = "SELECT * FROM stock_purchase_items WHERE stock_item_id='$stock_item_id' ORDER BY date DESC";
			$result_spi = mysqli_query($con,$query_spi);
			$row_spi = mysqli_fetch_assoc($result_spi);

			$query_pl = "SELECT * FROM price_list WHERE stock_item_id='$stock_item_id' AND 
			company_id='$company_id' AND branch_id='$branch_id' ORDER BY date DESC";
			$result_pl = mysqli_query($con,$query_pl);
			if(!empty($result_pl) && mysqli_num_rows($result_pl) > 0)
			{
				$row_pl = mysqli_fetch_assoc($result_pl);
				$pl_price = $row_pl['price'];
			}
			else
			{
				$pl_price = 0;
			};

			$query = "SELECT * FROM stock_items WHERE stock_item_id='$stock_item_id'";
			$result = mysqli_query($con,$query);
			$row = mysqli_fetch_assoc($result);
			$price = $row['price_cash'];
			if($company_id == 11)
			{
				if($price =='' || $price < 1)
				{
					$selling_price = round(($row_spi['price'] + ($row_spi['price'] * $row['margin_site'])), 2);
				}
				else
				{
					$selling_price = $price;
				};
			}
			else
			{
				if($pl_price > 0)
				{
					$selling_price = $pl_price;
				}
				else
				{
					$selling_price = $price;
				};
			};
			
			array_push($data, 
				$selling_price,
				$row['block_negative']
			);
			echo json_encode($data);
		}

		function stock_sales_block_negative()
		{
			global $con;
			$item_id = $_POST['stock_item_id'];
			$company_id = $_SESSION['company_id'];
			$warehouse = $_SESSION['warehouse_id'];
			$balance = 0;
			$query="SELECT item_id, SUM(qty_in) AS qty_in, SUM(qty_out) AS qty_out FROM
			(SELECT stock_item_id  AS item_id, warehouse_id, 0 AS qty_out, qty AS qty_in FROM stock_purchase_items 
			WHERE warehouse_id ='$warehouse' AND stock_item_id = '$item_id' AND company_id = '$company_id'
			UNION ALL SELECT stock_item_id AS item_id, warehouse_id, qty AS qty_out, 0 AS qty_in FROM stock_sales_items 
			WHERE warehouse_id ='$warehouse' AND stock_item_id = '$item_id' AND company_id = '$company_id'
			UNION ALL SELECT stock_id AS item_id, warehouse_id, qty AS qty_out, 0 AS qty_in FROM mtce_stock_list 
			WHERE warehouse_id ='$warehouse' AND stock_id = '$item_id' AND company_id = '$company_id'
			UNION ALL SELECT stock_item_id AS item_id,warehouse_id, qty_out AS qty_out, 0 AS qty_in FROM stock_adjustment_items 
			WHERE warehouse_id ='$warehouse' AND stock_item_id = '$item_id' AND company_id = '$company_id'
			UNION ALL SELECT stock_item_id AS item_id, warehouse_id, qty_transferred AS qty_out, 0 AS qty_in FROM stock_transfer_items 
			WHERE warehouse_id ='$warehouse' AND stock_item_id = '$item_id' AND company_id = '$company_id'
			UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS qty_out, qty_in AS qty_in FROM stock_adjustment_items 
			WHERE warehouse_id ='$warehouse' AND stock_item_id = '$item_id' AND company_id = '$company_id'
			UNION ALL SELECT stock_item_id AS item_id, warehouse_id, 0 AS qty_out, qty_received AS qty_in FROM stock_transfer_items 
			WHERE warehouse_id ='$warehouse' AND stock_item_id = '$item_id' AND company_id = '$company_id') AS c GROUP BY item_id";
			$query_run = mysqli_query($con, $query);
			$row = mysqli_fetch_assoc($query_run);
			$balance = $row['qty_in'] - $row['qty_out'];
			echo $balance;
		}

		function save_stock_sales()
		{
			global $con;
			$sales_debit = $_POST['stock_sales_debit'];
			$sales_credit = $_POST['stock_sales_credit'];
			$sales_amount = $_POST['stock_sales_amount'];
			$sales_supplied_by = $_POST['stock_sales_supplied_by'];
			$_SESSION['customer_name'] = $_POST['stock_sales_supplied_by'];
			$sales_ref_no = $_POST['stock_sales_ref_no'];
			$sales_date = $_POST['stock_sales_date'];
			$sales_received_by = $_POST['stock_sales_received_by'];
			$sales_narration = $_POST['stock_sales_narration'];
			$vat_type = $_POST['stock_sales_vat_type'];
			$calc_type = $_POST['stock_sales_calc_type'];
			$covid_rate = $_POST['stock_sales_covid_rate'];
			$covid_amount = $_POST['stock_sales_covid_amount'];
			$getfund_rate = $_POST['stock_sales_getfund_rate'];
			$getfund_amount = $_POST['stock_sales_getfund_amount'];
			$nhil_rate = $_POST['stock_sales_nhil_rate'];
			$nhil_amount = $_POST['stock_sales_nhil_amount'];
			$total_levies = $_POST['stock_sales_total_levies_amount'];
			$total_after_levies = $_POST['stock_sales_total_after_levies_amount'];
			$vat_rate = $_POST['stock_sales_vat_rate'];
			$vat_amount = $_POST['stock_sales_vat_amount'];
			
			$discount_perc = $_POST['stock_sales_discount_rate'];
			$discount = $_POST['stock_sales_discount_amount'];
			$sub_total = $_POST['stock_sales_sub_total_amount'];
			$total = $_POST['stock_sales_total_amount'];
			$company_id = $_SESSION['company_id'];
			if(isset($_POST['stock_sales_branch_id']) && $_POST['stock_sales_branch_id'] > 0)
			{
				$branch_id = $_POST['stock_sales_branch_id'];
			}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};
			$user_id = $_SESSION['user_id'];
			$unique = $_POST['stock_sales_unique'];

			if($company_id > 0)
			{
				$query_uniq = "SELECT * FROM stock_sales WHERE stock_sales_unique = '$unique'";
				$result_uniq = mysqli_query($con,$query_uniq);
				if(!empty($result_uniq) && mysqli_num_rows($result_uniq) > 0)
				{
					echo 'exist';
				}
				else
				{
					$query = "SELECT sno FROM stock_sales WHERE company_id = '$company_id' ORDER BY sno DESC";
					$result = mysqli_query($con,$query);
					$row = mysqli_fetch_assoc($result);
					$sno = $row['sno'] + 1;

					$query = "INSERT INTO `stock_sales`(
					`company_id`, `date`, `ledger_debit`, `ledger_credit`, `amount`, `reference_no`, `supplied_by`, 
					`received_by`, `narration`, `sno`, `branch_id`, `created_by`, `created_datetime`,`vat_type`, 
					`vat_calc_type`, `covid_perc`,`nhil_perc`, `getfund_perc`, `vat_perc`, `covid`, `getfund`, 
					`nhil`, `vat`, `total_levies`, `total_after_levies`, `discount_perc`, `discount`, `sub_total`, `total`,
					`stock_sales_unique`) 
					VALUES ('$company_id','$sales_date','$sales_debit','$sales_credit','$sales_amount',
					'$sales_ref_no','$sales_supplied_by',
					'$sales_received_by','$sales_narration','$sno','$branch_id','$user_id',NOW(),'$vat_type','$calc_type','$covid_rate','$nhil_rate','$getfund_rate','$vat_rate',
					'$covid_amount','$getfund_amount','$nhil_amount','$vat_amount','$total_levies','$total_after_levies',
					'$discount_perc','$discount','$sub_total','$total','$unique')";
					$query_run = mysqli_query($con, $query);

					if ($query_run) 
					{
						//POST TRANSACTION
							$query = "SELECT * FROM stock_sales ORDER BY stock_sales_id DESC";
							$result = mysqli_query($con,$query);
							$row = mysqli_fetch_assoc($result);
							$stock_sales_id = $row['stock_sales_id'];
							
							$_SESSION['stock_sales_id'] = $row['stock_sales_id'];

							$query_dr = "INSERT INTO `transactions`(
							`company_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
							'$company_id','$stock_sales_id','$sales_debit','$sales_credit','$sales_date','$sales_amount','$sales_amount','$sales_narration')";
							mysqli_query($con, $query_dr);

							$query_cr = "INSERT INTO `transactions`(
							`company_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
							'$company_id','$stock_sales_id','$sales_credit','$sales_debit','$sales_date','$sales_amount','$sales_amount','$sales_narration')";
							mysqli_query($con, $query_cr);

							$number_as = count($_POST["stock_sales_desc"]);  
							if($number_as > 0)  
							{  
								for($i=0; $i<$number_as; $i++)  
								{  
									if(trim($_POST["stock_sales_desc"][$i] !== '') && trim($_POST["stock_sales_desc"][$i] !== 0))  
									{  
										$stock_sales_desc = $_POST['stock_sales_desc'][$i];
										$stock_sales_loc = $_POST['stock_sales_loc'][$i];
										$stock_sales_qty = $_POST['stock_sales_qty'][$i];
										$stock_sales_price = $_POST['stock_sales_price'][$i];
										$stock_sales_amt = $_POST['stock_sales_amt'][$i];
										$stock_sales_batch = $_POST['stock_sales_batch'][$i];
										$stock_sales_expiry_date = $_POST['stock_sales_expiry_date'][$i];
										$query = "INSERT INTO `stock_sales_items`
										(`company_id`,`branch_id`, `stock_sales_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, 
										`amount`, `batch`, `expiry_date`, `qty`, `created_by`, `created_datetime`) VALUES 
										('$company_id','$branch_id','$stock_sales_id','$stock_sales_desc','$stock_sales_loc',
										'$sales_date','$stock_sales_price','$stock_sales_amt','$stock_sales_batch',
										'$stock_sales_expiry_date','$stock_sales_qty','$user_id', NOW())";
										mysqli_query($con, $query);
									};
								}
								echo "saved";
								//$_SESSION['sales_display_user_id'] = $user_id;
								//$_SESSION['sales_display_user_super_id'] = $user_super_id;
								$_SESSION['stock_sales_id'] = $stock_sales_id;
							}  
							else  
							{  
								echo "empty";  
							};
					};
				};
			};
		}

		function edit_stock_sales()
		{
			global $con;
			$stock_sales_id = $_POST['stock_sales_id'];
			$data=array();
			$query = "SELECT * FROM stock_sales WHERE stock_sales_id='$stock_sales_id'";
			$result = mysqli_query($con,$query);
			while($row = mysqli_fetch_assoc($result))
			{
				array_push($data, 
					$row['stock_sales_id'],$row['date'],$row['ledger_debit'],$row['ledger_credit'],
					$row['amount'],$row['reference_no'],$row['supplied_by'],$row['received_by'],$row['narration'],
					$row['branch_id'],$row['vat_type'], $row['vat_calc_type'], $row['covid_perc'], $row['nhil_perc'], 
					$row['getfund_perc'], $row['vat_perc'], $row['covid'], $row['getfund'], $row['nhil'], $row['vat'], 
					$row['total_levies'], $row['total_after_levies'], $row['discount'], $row['discount_perc'], 
					$row['sub_total'], $row['total']
				);
			}
			echo json_encode($data);
		}

