	    function update_stock_sales()
		{
			global $con;
			$stock_sales_id = $_POST['stock_sales_id'];
			//$branch_id = $_POST['stock_sales_branch_id'];
			$sales_debit = $_POST['stock_sales_debit'];
			$sales_credit = $_POST['stock_sales_credit'];
			$sales_amount = $_POST['stock_sales_amount'];
			$sales_supplied_by = $_POST['stock_sales_supplied_by'];
			$_SESSION['customer_name'] = $_POST['stock_sales_supplied_by'];
			$sales_ref_no = $_POST['stock_sales_ref_no'];
			$sales_date = $_POST['stock_sales_date'];
			$sales_received_by = $_POST['stock_sales_received_by'];
			$sales_narration = $_POST['stock_sales_narration'];
			$vat_type = $_POST['stock_sales_vat_type'];
			$calc_type = $_POST['stock_sales_calc_type'];
			$covid_rate = $_POST['stock_sales_covid_rate'];
			$covid_amount = $_POST['stock_sales_covid_amount'];
			$getfund_rate = $_POST['stock_sales_getfund_rate'];
			$getfund_amount = $_POST['stock_sales_getfund_amount'];
			$nhil_rate = $_POST['stock_sales_nhil_rate'];
			$nhil_amount = $_POST['stock_sales_nhil_amount'];
			$total_levies = $_POST['stock_sales_total_levies_amount'];
			$total_after_levies = $_POST['stock_sales_total_after_levies_amount'];
			$vat_rate = $_POST['stock_sales_vat_rate'];
			$vat_amount = $_POST['stock_sales_vat_amount'];
			
			$discount_perc = $_POST['stock_sales_discount_rate'];
			$discount = $_POST['stock_sales_discount_amount'];
			$sub_total = $_POST['stock_sales_sub_total_amount'];
			$total = $_POST['stock_sales_total_amount'];
			$company_id = $_SESSION['company_id'];
			$user_id = $_SESSION['user_id'];
			if(isset($_POST['stock_sales_branch_id']) && $_POST['stock_sales_branch_id'] > 0)
			{
				$branch_id = $_POST['stock_sales_branch_id'];
			}
			else
			{
				$branch_id = $_SESSION['branch_id'];
			};

			if($company_id > 0)
			{
				$query = "UPDATE `stock_sales` SET `date`='$sales_date',`ledger_debit`='$sales_debit',
				`amount`='$sales_amount',`reference_no`='$sales_ref_no',`branch_id`='$branch_id',
				`supplied_by`='$sales_supplied_by',`received_by`='$sales_received_by',`altered_by`='$user_id',
				`altered_datetime`=NOW(), `narration`='$sales_narration',
				`vat_type`='$vat_type', `vat_calc_type`='$calc_type', `covid_perc`='$covid_rate',
				`nhil_perc`='$nhil_rate', `getfund_perc`='$getfund_rate', `vat_perc`='$vat_rate', 
				`covid`='$covid_amount', `getfund`='$getfund_amount', `nhil`='$nhil_amount', 
				`vat`='$vat_amount', `total_levies`='$total_levies', `total_after_levies`='$total_after_levies',
				`discount_perc`='$discount_perc', `discount`='$discount', `sub_total`='$sub_total',
				`total`='$total' WHERE `stock_sales_id`='$stock_sales_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					//POST TRANSACTION
					if(isset($stock_sales_id) && $stock_sales_id > 0)
					{
						$query_trans_del = "DELETE FROM `transactions` WHERE `stock_sales_id`='$stock_sales_id'";
						mysqli_query($con, $query_trans_del);

						$query_trans_del = "DELETE FROM `stock_sales_items` WHERE `stock_sales_id`='$stock_sales_id'";
						mysqli_query($con,$query_trans_del);

						$query_dr = "INSERT INTO `transactions`(
						`company_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_debit`, `narration`) VALUES (
						'$company_id','$stock_sales_id','$sales_debit','$sales_credit','$sales_date','$sales_amount','$sales_amount','$sales_narration')";
						mysqli_query($con, $query_dr);

						$query_cr = "INSERT INTO `transactions`(
						`company_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, `amount_credit`, `narration`) VALUES (
						'$company_id','$stock_sales_id','$sales_credit','$sales_debit','$sales_date','$sales_amount','$sales_amount','$sales_narration')";
						mysqli_query($con, $query_cr);


						$number_as = count($_POST["stock_sales_desc"]);  
						if($number_as > 0)  
						{  
						for($i=0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["stock_sales_desc"][$i] !== '') && trim($_POST["stock_sales_desc"][$i] !== 0))  
							{  
									$stock_sales_desc = $_POST['stock_sales_desc'][$i];
									$stock_sales_loc = $_POST['stock_sales_loc'][$i];
									$stock_sales_qty = $_POST['stock_sales_qty'][$i];
									$stock_sales_price = $_POST['stock_sales_price'][$i];
									$stock_sales_amt = $_POST['stock_sales_amt'][$i];
									$stock_sales_batch = $_POST['stock_sales_batch'][$i];
									$stock_sales_expiry_date = $_POST['stock_sales_expiry_date'][$i];
									$query = "INSERT INTO `stock_sales_items`
									(`company_id`, `branch_id`, `stock_sales_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, 
									`amount`, `batch`, `expiry_date`, `qty`, `created_by`, `created_datetime`) VALUES ('$company_id',
									'$branch_id','$stock_sales_id','$stock_sales_desc','$stock_sales_loc','$sales_date',
									'$stock_sales_price','$stock_sales_amt','$stock_sales_batch','$stock_sales_expiry_date',
									'$stock_sales_qty','$user_id',NOW())";
									mysqli_query($con, $query);
							};
								$_SESSION['stock_sales_id'] = $stock_sales_id;
						};
						echo "Stock Sales Items Updated";  
						}  
						else  
						{  
						echo "Stock Sales Items NOT Updated";  
						};
					};
				};
			};
		}

		function reprint_stock_sales()
		{
			global $con;
			$_SESSION['stock_sales_id'] = $_POST['stock_sales_id'];
		}

		function delete_stock_sales()
		{
			global $con;
			if(isset($_POST['stock_sales_id']) && $_POST['stock_sales_id'] > 0)
			{
				$stock_sales_id = $_POST['stock_sales_id'];
				$query = "DELETE FROM `stock_sales`WHERE `stock_sales_id`='$stock_sales_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) {
					$query_trans_del = "DELETE FROM `transactions` WHERE `stock_sales_id`='$stock_sales_id'";
					mysqli_query($con, $query_trans_del);

					$query_sold_item_del = "DELETE FROM `stock_sales_items` WHERE `stock_sales_id`='$stock_sales_id'";
					mysqli_query($con, $query_sold_item_del);
					
					echo "Sales DELETED Successfully";  
				}  
				else  
				{  
				echo "Sales NOT DELETED";  
				};
			};
		}

