		function order_set_item()
		{
			global $con;
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$search = $_POST['search'];
			$value= '<table class="table table-hover table-bordered table-sm" id="order_table_list" width="100%" cellspacing="0">
				<thead>
				</thead>
				<tbody class="pv-table-body">';
										
					$i=0;
					$query = "SELECT st.*, pl.price FROM stock_items st JOIN
					price_list pl ON (st.stock_item_id=pl.stock_item_id AND st.branch_id=pl.branch_id) WHERE 
					(st.company_id = '$company_id' AND st.branch_id = '$branch_id' AND st.stock_item LIKE '%".$search."%')";
					
					$result = mysqli_query($con,$query);
					while($row = mysqli_fetch_array($result))
					{
						$i++;
						if($i==1)
						{
							$value .='<tr>';
						};
							$value .=' <td class="action-td">
								<h5 class="card-title">'.$row['price'].'</h5>
								<a href="#" class="btn btn-primary btn-block" data="'.$row['stock_item_id'].'">
									<small>'.$row['stock_item'].'</small>
								</a>
							</td>';
						if($i ==3)
						{
							$i=0;
							$value .= '</tr>';
						};
					};
				
					$value .= '</tbody>
			</table>';
			echo $value;
		}

