		function edit_order()
		{
			global $con;
			$table_order_id = $_POST['table_order_id'];
			$id = $_POST['id'];
			$order_details=array();
			$i=0;
			$value = '<table class="table table-hover table-bordered table-sm" id="order_item_list_table" width="100%" cellspacing="0">
				<thead>
					<tr>
						<th class="action-td" colspan="5">Order Items</th>
					</tr>
					<tr>
						<th class="action-td" width="50%">Items</th>
						<th class="action-td" width="10%">Qty</th>
						<th class="action-td" width="10%">Price</th>
						<th class="action-td" width="20%">Amount</th>
						<th class="action-td" width="10%">Action</th>
					</tr>
				</thead>
				<tbody class="pv-table-body">';
				$query_tol = "SELECT * FROM table_order_list WHERE table_order_id='$table_order_id'";
				$result_tol = mysqli_query($con,$query_tol);
				while($row_tol = mysqli_fetch_assoc($result_tol))
				{
					$i++;
					$stock_item_id = $row_tol['stock_item_id'];
					$qty = $row_tol['qty'];
					$price = $row_tol['price'];
					$amount = $row_tol['amount'];
					$price_f = number_format($price, 2, '.', ',');
					$amount_f = number_format($amount, 2, '.', ',');
					$query_stock = "SELECT * FROM stock_items WHERE stock_item_id = '$stock_item_id'";
					$query_run_stock = mysqli_query($con, $query_stock);
		
					if (mysqli_num_rows($query_run_stock) > 0)
					{
						while($row_stock = mysqli_fetch_assoc($query_run_stock))
						{
							$stock_item = $row_stock['stock_item'];
						}
					}
					else
					{
						$stock_item = 'Not Specified';
					};
					$value .= '<tr id="'.$i.'">
						<td>'.$stock_item.'
							<input type="text" class="form-control" value="'.$stock_item_id.'" name="order_item_list_stock_item_id[]" id="order_item_list_stock_item_id'.$i.'" hidden="true">
						</td>
						<td class="action-td">'.$qty.'
							<input type="text" class="form-control" value="'.$qty.'" name="order_item_list_qty[]" id="order_item_list_qty'.$i.'" hidden="true">
						</td>
						<td class="amt-td">'.$price_f.'
							<input type="text" class="form-control" value="'.$price.'" name="order_item_list_price[]" id="order_item_list_price'.$i.'" hidden="true">
						</td>
						<td class="amt-td">'.$amount_f.'
							<input type="text" class="form-control order_item_list_amount" value="'.$amount.'" name="order_item_list_amount[]" id="order_item_list_amount'.$i.'" hidden="true">
						</td>
						<td class="action-td">';
						if($id=='order_edit_btn')
						{
							$value .= '<a href="#" id="order_item_list_delete" class="order_item_list_delete" data-id="'.$i.'"><i class="fa fa-trash fa-sm"></i></a>';
						};
						$value .= '</td>
					</tr>';
				};
				$value .= '</tbody>
			</table>';
			$query = "SELECT * FROM table_order WHERE table_order_id='$table_order_id'";
			$result = mysqli_query($con,$query);
			while($row = mysqli_fetch_assoc($result))
			{
				$served = '<a href="#" id="order_serve_btn" class="btn btn-primary" data-id="'.$row['table_order_id'].'">Serve</a>';
				$unserved = '<a href="#" id="order_pending_btn" class="btn btn-warning" data-id="'.$row['table_order_id'].'">Unserve</a>';
				$pay = '<a href="#" id="order_pay_btn" class="btn btn-primary" data-order="'.$row['table_order_id'].'" 
                    data-table="'.$row['dining_table_id'].'" data-debit="'.$row['ledger_debit'].'"
                    data-amount="'.$row['amount'].'">Pay
				</a>';
				$print = '<a href="#" id="order_print_btn" class="btn btn-success" data-id="'.$row['table_order_id'].'">Print</a>';
				array_push($order_details, 
					$row['table_order_id'], $row['dining_table_id'], $row['date'], $row['ledger_debit'],
					$row['instruction'], $row['amount'], $value, $row['customer_name'], $row['customer_phone'],
					$served, $unserved, $pay, $print, $row['status']
				);
			}
			echo json_encode($order_details);
		}

