		function delete_order()
		{
			global $con;
			
			$userdetail = $_SESSION['full_name'].':-'.time();
			if(isset($_POST['table_order_id']) && $_POST['table_order_id'] > 0)
			{
				$table_order_id = $_POST['table_order_id'];
				$query = "DELETE FROM `table_order` WHERE `table_order_id`='$table_order_id'";
				$query_run = mysqli_query($con, $query);

				if ($query_run) 
				{
					$query_del = "DELETE FROM table_order_list WHERE `table_order_id`='$table_order_id'";
					mysqli_query($con, $query_del);
					$query_del = "DELETE FROM stock_sales WHERE `table_order_id`='$table_order_id'";
					mysqli_query($con, $query_del);
					$query_del = "DELETE FROM stock_sales_items WHERE `table_order_id`='$table_order_id'";
					mysqli_query($con, $query_del);
					$query_del = "UPDATE receipt SET deleted='$userdetail' WHERE `table_order_id`='$table_order_id'";
					mysqli_query($con, $query_del);
					$query_del = "DELETE FROM `transactions` WHERE `table_order_id`='$table_order_id'";
					mysqli_query($con, $query_del);
				};
			};
		}


