		function proforma_item_price()
		{
			global $con;
			$stock_item_id = $_POST['stock_item_id'];
			$data=array();
			$query = "SELECT * FROM stock_items WHERE stock_item_id='$stock_item_id'";
			$result = mysqli_query($con,$query);
			while($row=mysqli_fetch_assoc($result))
			{
				array_push($data, 
					$row['price_cash']
				);
			}
			echo json_encode($data);
		}

		function save_proforma()
		{
			global $con;
			$proforma_id = $_POST['proforma_id'];
			$customer = $_POST['proforma_customer'];
			$address = $_POST['proforma_customer_address'];
			$telephone = $_POST['proforma_customer_telephone'];
			$amount = $_POST['proforma_amount'];
			$narration = $_POST['proforma_narration'];
			$date = $_POST['proforma_date'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];

			$query = "SELECT sno FROM proforma WHERE company_id = '$company_id' ORDER BY sno DESC";
			$result = mysqli_query($con,$query);
			$row = mysqli_fetch_assoc($result);
			$sno = $row['sno'] + 1;

			$query = "INSERT INTO `proforma`(
			`company_id`, `date`, `customer`, `address`, `telephone`, `amount`, `narration`, 
			`sno`, `branch_id`, `created_by`, `created_datetime`) 
			VALUES ('$company_id','$date','$customer','$address','$telephone',
			'$amount','$narration','$sno','$branch_id','$user_id',NOW())";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				//POST TRANSACTION
					$query = "SELECT * FROM proforma ORDER BY proforma_id DESC";
					$result = mysqli_query($con,$query);
					$row = mysqli_fetch_assoc($result);
					$proforma_id = $row['proforma_id'];
					
					$_SESSION['proforma_id'] = $row['proforma_id'];

					$number_as = count($_POST["proforma_desc"]);  
					if($number_as > 0)  
					{  
						for($i=0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["proforma_desc"][$i] !== '') && trim($_POST["proforma_desc"][$i] !== 0))  
							{  
								$proforma_desc = $_POST['proforma_desc'][$i];
								$proforma_loc = $_POST['proforma_loc'][$i];
								$proforma_qty = $_POST['proforma_qty'][$i];
								$proforma_price = $_POST['proforma_price'][$i];
								$proforma_amt = $_POST['proforma_amt'][$i];
								$query = "INSERT INTO `proforma_items`
