		function update_proforma()
		{
			global $con;
			$proforma_id = $_POST['proforma_id'];
			$customer = $_POST['proforma_customer'];
			$address = $_POST['proforma_customer_address'];
			$telephone = $_POST['proforma_customer_telephone'];
			$amount = $_POST['proforma_amount'];
			$narration = $_POST['proforma_narration'];
			$date = $_POST['proforma_date'];
			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];

			$query = "UPDATE `proforma` SET `date`='$date', `customer`='$customer', `address`='$address', 
			`telephone`='$telephone', `amount`='$amount', `narration`='$narration', 
			`altered_by`='$user_id', `altered_datetime`=NOW()";
			$query_run = mysqli_query($con, $query);

			if ($query_run) 
			{
				$query = "DELETE FROM `proforma_items` WHERE `proforma_id`='$proforma_id'";
				mysqli_query($con,$query);

				$number_as = count($_POST["proforma_desc"]);  
				if($number_as > 0)  
				{  
					for($i=0; $i<$number_as; $i++)  
					{  
						if(trim($_POST["proforma_desc"][$i] !== '') && trim($_POST["proforma_desc"][$i] !== 0))  
						{  
							$proforma_desc = $_POST['proforma_desc'][$i];
							$proforma_loc = $_POST['proforma_loc'][$i];
							$proforma_qty = $_POST['proforma_qty'][$i];
							$proforma_price = $_POST['proforma_price'][$i];
							$proforma_amt = $_POST['proforma_amt'][$i];
							$query = "INSERT INTO `proforma_items`
							(`company_id`, `proforma_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, `amount`, 
							`qty`, `branch_id`, `created_by`, `created_datetime`) VALUES 
							('$company_id','$proforma_id','$proforma_desc','$proforma_loc','$date','$proforma_price',
							'$proforma_amt','$proforma_qty','$branch_id','$user_id',NOW())";
							mysqli_query($con, $query);
						};
					};
				};
			};
		}

