			$query = "SELECT sno FROM stock_sales WHERE company_id = '$company_id' 
			AND branch_id = '$branch_id' ORDER BY sno DESC";
			$result = mysqli_query($con,$query);
			if (mysqli_num_rows($result) > 0)
			{
				$row = mysqli_fetch_assoc($result);
				$sno = $row['sno'] + 1;
			}
			else
			{
				$sno = 1;
			};

			$query = "INSERT INTO `stock_sales`(
			`company_id`,`date`, `ledger_credit`, `amount`, `reference_no`, `warehouse_id`,
			`supplied_by`, `received_by`, `narration`, `sno`, `branch_id`, `customer_id`, `age`, 
			`id_number`,`total_payment_option`, `cash_tendered`, `balance`, `total_invoice_value`, 
			`discount`, `tax`, `net_amount`,`created_by`, `created_datetime`) 
			VALUES ('$company_id','$date','$sales_credit','$payment_option_total','$sno','$warehouse_id',
			'$full_name','$customer_name','$sales_narration','$sno','$branch_id','$customer_id',
			'$customer_age','$customer_id_number','$payment_option_total','$cash_tendered','$change',
			'$sub_total','$discount','$tax','$net_amount','$user_id',NOW())";
			$query_run = mysqli_query($con, $query);
			
			if ($query_run) 
