			$cash_tendered = $_POST['payment_option_cash_tendered'];
			$change = $_POST['payment_option_change'];
			$warehouse_id = $_POST['stock_sales_invoice_default_warehouse'];
			$date = $_POST['default_date'];
			$sales_credit = 35;
			$sales_narration = "GOODS SOLD TO ".$customer_name;
			$sub_total = $_POST['stock_sales_invoice_sub_total'];
			$discount = $_POST['stock_sales_invoice_discount'];
			$tax = $_POST['stock_sales_invoice_tax'];
			$net_amount = $_POST['stock_sales_invoice_net_total'];

			$company_id = $_SESSION['company_id'];
			$branch_id = $_SESSION['branch_id'];
			$user_id = $_SESSION['user_id'];
			$full_name = $_SESSION['full_name'];

			$query = "UPDATE `stock_sales` SET
			`date`='$date', `ledger_credit`='$sales_credit', `amount`='$payment_option_total', 
			`warehouse_id`='$warehouse_id',`supplied_by`='$full_name', `received_by`='$customer_name', 
			`narration`='$sales_narration', `customer_id`='$customer_id', `age`='$customer_age', 
			`id_number`='$customer_id_number',`total_payment_option`='$payment_option_total', 
			`cash_tendered`='$cash_tendered', `balance`='$change', `total_invoice_value`='$sub_total', 
			`discount`='$discount', `tax`='$tax', `net_amount`='$net_amount' WHERE `stock_sales_id`='$stock_sales_id'";
			$query_run = mysqli_query($con, $query);
			
			if ($query_run) 
			{
				if(isset($stock_sales_id) && $stock_sales_id > 0)
				{
					//POST TRANSACTION
					$query = "DELETE FROM `transactions` WHERE stock_sales_id='$stock_sales_id'";
					mysqli_query($con,$query);

					$query = "DELETE FROM stock_sales_items WHERE stock_sales_id='$stock_sales_id'";
					mysqli_query($con,$query);

					$_SESSION['stock_sales_id'] = $stock_sales_id;
					$_SESSION['customer_name'] = $customer_name;

					$ledger_as = count($_POST["payment_option_ledger_id"]);  
					if($ledger_as > 0)  
					{  
						for($i = 0; $i < $ledger_as; $i++)
						{  
							if(trim($_POST["payment_option_ledger_id"][$i] != '') && trim($_POST["payment_option_ledger_id"][$i] != 0))  
							{  
								$sales_debit = $_POST['payment_option_ledger_id'][$i];
								$sales_amount = $_POST['payment_option_ledger_amount'][$i];
								
								$query_dr = "INSERT INTO `transactions`(
								`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, 
								`amount_debit`, `narration`,`created_by`, `created_datetime`) VALUES (
								'$company_id','$branch_id','$stock_sales_id','$sales_debit','$sales_credit','$date',
								'$sales_amount','$sales_amount','$sales_narration','$user_id',NOW())";
								mysqli_query($con, $query_dr);
			
								$query_cr = "INSERT INTO `transactions`(
								`company_id`,`branch_id`,`stock_sales_id`,`ledger_id`, `ledger_id_contra`, `date`, `amount`, 
								`amount_credit`, `narration`,`created_by`, `created_datetime`) VALUES (
								'$company_id','$branch_id','$stock_sales_id','$sales_credit','$sales_debit','$date',
								'$sales_amount','$sales_amount','$sales_narration','$user_id',NOW())";
								mysqli_query($con, $query_cr);
							};
						};
					};

					$number_as = count($_POST["stock_sales_invoice_item_id"]);  
					if($number_as > 0)  
					{  
						for($i = 0; $i<$number_as; $i++)  
						{  
							if(trim($_POST["stock_sales_invoice_item_id"][$i] != '') && trim($_POST["stock_sales_invoice_item_id"][$i] != 0))  
							{  
								$stock_sales_invoice_item_id = $_POST['stock_sales_invoice_item_id'][$i];
								$stock_sales_invoice_item_qty = $_POST['stock_sales_invoice_item_qty'][$i];
								$stock_sales_invoice_item_price = $_POST['stock_sales_invoice_item_price'][$i];
								$stock_sales_invoice_item_amount = $_POST['stock_sales_invoice_item_amount'][$i];
								$query = "INSERT INTO `stock_sales_items`
								(`company_id`,`branch_id`, `stock_sales_id`, `stock_item_id`, `warehouse_id`, `date`, `price`, 
								`amount`, `qty`,`created_by`, `created_datetime`) VALUES 
								('$company_id','$branch_id','$stock_sales_id','$stock_sales_invoice_item_id','$warehouse_id','$date',
								'$stock_sales_invoice_item_price','$stock_sales_invoice_item_amount',
								'$stock_sales_invoice_item_qty','$user_id',NOW())";
								$query_run = mysqli_query($con, $query);
							}; 
						};
					};
				};
		    };
		}

