	//SMS
		function save_sms_purchase()
		{
			global $con;
			$sms_qty = $_POST['sms_qty'];
			$sms_date = $_POST['sms_date'];
			$company_id = $_SESSION['company_id'];

			$query_last_sno = "SELECT `sno` FROM `sms` WHERE `company_id` = '$company_id' ORDER BY `sno` DESC";
			$result_last_sno = mysqli_query($con,$query_last_sno);
			if(isset($result_last_sno))
			{
				$row_last_sno = mysqli_fetch_assoc($result_last_sno);
				if($row_last_sno['sno'] !=='' && $row_last_sno['sno'] > 0)
				{
					$last_sno = $row_last_sno['sno'];
				}
				else
				{
					$last_sno = 0;
				}
			}
			else
			{
				$last_sno = 0;
			};
			$next_sno = $last_sno + 1;
			
			$query = "INSERT INTO `sms`(`sno`,`company_id`,`date`, `qty_in`) VALUES ('$next_sno','$company_id','$sms_date','$sms_qty')";
			$query_run = mysqli_query($con, $query);

			if ($query_run)
			{
				list_sms();
			}
			else
			{
				echo "SMS NOT Added";
			};
		}

		function list_sms()
		{
			global $con;
			$company_id = $_SESSION['company_id'];
			$value='';
			$query = "SELECT * FROM sms WHERE qty_in !='' ORDER BY date ASC";
			$query_run = mysqli_query($con, $query);
			$value.='<table class="table table-hover table-bordered table-sm" id="smsTable" width="100%" cellspacing="0">
						<thead>
							<tr>
								<th>Company</th>
								<th class="action-td">Date</th>
								<th class="action-td">Qty</th>
								<th class="action-td">Action</th>
							</tr>
						</thead>
						<tbody class="pv-table-body">';
							
						if (mysqli_num_rows($query_run) > 0)
						{
							while($row = mysqli_fetch_assoc($query_run))
							{
								$company_id = $row['company_id'];
								$sql_company = "SELECT * FROM company WHERE company_id = '$company_id' ORDER BY trading_name ASC";
								$result_company = mysqli_query($con,$sql_company);
								$row_company = mysqli_fetch_array($result_company);
					
								$value.='<tr>
									<td>'.$row_company['trading_name'].'</td>
									<td class="action-td">'.$row['date'].'</td>
									<td class="action-td">'.$row['qty_in'].'</td>
									<td class="action-td">
										<a href="#" id="btn_edit_sms_purchase" data-id="'.$row['sms_utility_id'].'">Edit</a>
										| 
										<a href="#" id="btn_delete_sms_purchase" data-id="'.$row['sms_utility_id'].'">Delete</a>
									</td>
								</tr>';
							}
						};
					$value.='</tbody>
					</table>';
					echo $value;
		}

		function edit_sms_purchase()
		{
			global $con;
			$sms_utility_id = $_POST['sms_utility_id'];
			$query = "SELECT * from sms where sms_utility_id='$sms_utility_id'";
			$result = mysqli_query($con,$query);
			$data=array();
			while($row=mysqli_fetch_assoc($result))
			{
				array_push($data, 
					$row['sms_utility_id'],
					$row['date'],
					$row['qty_in']
				);
			}
				echo json_encode($data);
		}

		function update_sms_purchase()
		{
			global $con;
			$sms_qty = stripslashes($_POST['sms_qty']);
			$sms_qty = mysqli_real_escape_string($con,$sms_qty);
			$sms_date = stripslashes($_POST['sms_date']);
			$sms_date = mysqli_real_escape_string($con,$sms_date);
			$sms_utility_id = stripslashes($_POST['sms_utility_id']);
			$sms_utility_id = mysqli_real_escape_string($con,$sms_utility_id);
			/*$sms_qty = $_POST['sms_qty'];
			$sms_date = $_POST['sms_date'];
			$sms_utility_id = $_POST['sms_utility_id'];*/
			
			$query = "UPDATE `sms` SET `date`='$sms_date', `qty_in`='$sms_qty' WHERE `sms_utility_id`='$sms_utility_id'";
			$query_run = mysqli_query($con, $query);

			if ($query_run)
			{
				list_sms();
			}
			else
			{
				echo "SMS NOT Updated";
			};
		}
