	    function update_stock_adjustment_voucher()
		{
			global $con;
			$stock_adj_id = stripslashes($_POST['stock_adj_id']);
			$stock_adj_id = mysqli_real_escape_string($con,$stock_adj_id);
			$stk_adj_adjusted_by = stripslashes($_POST['stk_adj_adjusted_by']);
			$stk_adj_adjusted_by = mysqli_real_escape_string($con,$stk_adj_adjusted_by);
			$stk_adj_ref_no = stripslashes($_POST['stk_adj_ref_no']);
			$stk_adj_ref_no = mysqli_real_escape_string($con,$stk_adj_ref_no);
			$stk_adj_date = stripslashes($_POST['stk_adj_date']);
			$stk_adj_date = mysqli_real_escape_string($con,$stk_adj_date);
			$stk_adj_narration = stripslashes($_POST['stk_adj_narration']);
			$stk_adj_narration = mysqli_real_escape_string($con,$stk_adj_narration);

			$query = "UPDATE `stock_adjustment`SET `reference_no`='$stk_adj_ref_no', `date`='$stk_adj_date', `narration`='$stk_adj_narration', `adjusted_by`='$stk_adj_adjusted_by' WHERE `stock_adj_id`='$stock_adj_id'";
		    	$query_run = mysqli_query($con, $query);

		    	if($query_run) 
				{
		    		$query = "UPDATE `stock_adjustment_items` SET `status`='' WHERE `stock_adj_id`='$stock_adj_id'";
					mysqli_query($con,$query);

		    		$number_as = count($_POST["stk_adj_item_id"]);  
					if($number_as > 0)  
					{  
						for($i=0; $i<$number_as; $i++)  
						{  
					       if(trim($_POST["stk_adj_item_id"][$i] !== '') && trim($_POST["stk_adj_item_id"][$i] !== 0))  
					       {  
								$stk_adj_item_id = stripslashes($_POST['stk_adj_item_id'][$i]);
								$stk_adj_item_id = mysqli_real_escape_string($con,$stk_adj_item_id);
								$stk_adj_item_list_id = stripslashes($_POST['stk_adj_item_list_id'][$i]);
								$stk_adj_item_list_id = mysqli_real_escape_string($con,$stk_adj_item_list_id);
								$item_cat_id = stripslashes($_POST['item_cat_id'][$i]);
								$item_cat_id = mysqli_real_escape_string($con,$item_cat_id);
								$stock_adj_wh = stripslashes($_POST['stock_adj_wh'][$i]);
								$stock_adj_wh = mysqli_real_escape_string($con,$stock_adj_wh);
								$stk_adj_qty_in = stripslashes($_POST['stk_adj_qty_in'][$i]);
								$stk_adj_qty_in = mysqli_real_escape_string($con,$stk_adj_qty_in);
								$stk_adj_qty_out = stripslashes($_POST['stk_adj_qty_out'][$i]);
								$stk_adj_qty_out = mysqli_real_escape_string($con,$stk_adj_qty_out);
								$stock_adj_batch_no = stripslashes($_POST['stock_adj_batch_no'][$i]);
								$stock_adj_batch_no = mysqli_real_escape_string($con,$stock_adj_batch_no);

					            if($stk_adj_item_list_id !== '' && $stk_adj_item_list_id !== 0)
						        {
						        	$query_stk_adj_items = "UPDATE `stock_adjustment_items` SET `stock_adj_id`='$stock_adj_id', `date`='$stk_adj_date', 
									`stock_item_id`='$stk_adj_item_id', `category_id`='$item_cat_id', `warehouse_id`='$stock_adj_wh', 
									`batch_no`='$stock_adj_batch_no', `qty_in`='$stk_adj_qty_in', `qty_out`='$stk_adj_qty_out', `status`='updated' 
									WHERE `stk_adj_item_id`='$stk_adj_item_list_id'";
						        }
						        else
						        {
						        	$query_stk_adj_items = "INSERT INTO `stock_adjustment_items`
						            (`stock_adj_id`, `date`, `stock_item_id`, `category_id`, `warehouse_id`, `batch_no`, `qty_in`, `qty_out`, `status`) VALUES 
						            ('$stock_adj_id','$stk_adj_date','$stk_adj_item_id','$item_cat_id','$stock_adj_wh','$stock_adj_batch_no','$stk_adj_qty_in','$stk_adj_qty_out','updated')";
						        };

								mysqli_query($con, $query_stk_adj_items);
					       };
					  	};

					  	$query = "DELETE FROM `stock_adjustment_items` WHERE `status`='' AND `stock_adj_id`='$stock_adj_id'";
						mysqli_query($con,$query);

					  	echo "Stock Adjustment Items Updated";  
					}  
					else  
					{  
						echo "Stock Adjustment Items NOT Updated";  
					};
		    	}
		}

